//! The agent loop (epic #1078, P2a). Provider-agnostic: drive any `LlmProvider`
//! through tool-using turns until it returns a final answer.

pub use elide_middle::elide_middle;
use self::human_bytes::human_bytes;
use self::estimate_tokens::estimate_tokens;
use self::is_transient_error::is_transient_error;
use self::normalize_tool_name::normalize_tool_name;
use self::jittered::jittered;

use crate::permissions::Permissions;
use crate::telemetry::Telemetry;
use llm::{LlmProvider, Msg, ToolCall, ToolDef, Turn, TurnResult};
use serde_json::Value;
use std::path::Path;
use std::time::Duration;

/// The handoff prompt the harness injects when the step budget is nearly spent.
///
/// NOT a request the agent is trusted to remember. The protocol used to say "run `bsc-checkpoint`
/// before you run out", which asks the model LEAST able to sustain a long horizon to notice, at
/// exactly the right moment, that it is about to lose the thread. The capability being relied on is
/// the one that is failing, and a skipped checkpoint is indistinguishable from one that was not
/// needed — so it could never be observed, only regretted.
pub const HANDOFF_PROMPT: &str = "You are nearly out of steps for this turn. Stop working and REPLY IN THIS MESSAGE — do not create a file, and do not use any tool. Say what you were doing, what you finished, what is left, and the exact next action to take. Do not start anything new.";

/// How many steps are held back from the budget so the turn can end with a handoff rather than
/// simply stopping. Two: one for the model to write it, one of slack for a tool call it still owes.
pub const HANDOFF_RESERVE: usize = 2;

/// A checkpoint assembled from the CONVERSATION ALONE — no model cooperation of any kind.
///
/// This is the floor. Whatever the model did or did not do at the handoff prompt, these facts are
/// true and derivable: how far the turn got, which tools ran, and what it last said. A weak model
/// that ignores the handoff still leaves its successor oriented.
///
/// Deliberately NOT a transcript. The next launch reads this through `composeStartupPrompt`, and
/// handing a small model its own 20-step history is close to handing it nothing.
/// How ONE tool call is described to a human — its name plus the single most identifying argument.
///
/// Shared by the pane's live `[tool]` line and the checkpoint, so a call reads the same in both. The
/// pane used to print only `[tool] bash`, which for a session whose whole surface IS bash says
/// nothing: every step looked identical, and progress was indistinguishable from a loop.
///
/// Takes the name SEPARATELY because the pane prints the RESOLVED canonical name (a near-miss like
/// `file__create` is mapped before it is traced) while the checkpoint reads the raw call.
///
/// NEVER the whole argument blob. This reaches a terminal AND a checkpoint the next launch inlines
/// into its prompt, and tool args carry file contents.
pub fn describe_tool_call(name: &str, args: &Value) -> String {
    let target = args
        .get("path")
        .or_else(|| args.get("file"))
        .or_else(|| args.get("command"))
        .or_else(|| args.get("pattern"))
        .or_else(|| args.get("query"))
        .and_then(|v| v.as_str())
        .unwrap_or("");
    // One line, bounded — a multi-line command would break the pane's single-line cadence.
    let target = elide_middle(target.lines().next().unwrap_or(""), CALL_ARG_WIDTH);
    if target.trim().is_empty() { name.to_string() } else { format!("{name} {target}") }
}

/// How much of a tool's identifying argument the pane shows.
pub const CALL_ARG_WIDTH: usize = 96;


/// Tell the model, plainly, that it just made a call it already made and got the same bytes back.
///
/// OBSERVED on the twitter-clone-test director, in its own words: "I've been running the same command
/// repeatedly." Six of its twenty steps went to one loop. The agent already holds the full message
/// list, so an identical `(name, args)` pair is a cheap exact comparison — nothing was missing but
/// the sentence. A strong model notices on its own; a 9B local model burns a third of its budget
/// first, which is the gap `epic-reasoning-author-verifiable-logic-steps-that-let-weak-local-models-solve-hard-problems`
/// exists to close.
///
/// TWO RULES KEEP THE NOTICE FROM BECOMING THE NOISE IT WARNS ABOUT.
///
/// It fires only when the RESULT IS BYTE-IDENTICAL to the earlier one. A repeat that returned
/// something different was productive — `git status` after a commit, a file re-read after a write,
/// a directory listed again once it was populated — and saying nothing is correct there. What is
/// left is exactly the useless case: the same call, the same bytes, no new information. This is why
/// the check is not a tool allowlist; whether a repeat was worth making is a property of what came
/// back, not of which tool ran.
///
/// And it is scoped to the CURRENT TURN — the messages since the last user message, which is the
/// unit the step budget is spent in. Re-checking state at the top of each turn is ordinary work;
/// doing it six times inside one turn is the loop.
fn repeat_notice(messages: &[Msg], name: &str, args: &Value, output: &str) -> Option<String> {
    let turn = messages
        .iter()
        .rposition(|m| matches!(m, Msg::User(_)))
        .map(|i| &messages[i + 1..])
        .unwrap_or(messages);
    // Prior identical calls THIS TURN whose result was also identical. A call is paired to its
    // result by id — the pairing every provider already requires, so it is always present.
    //
    // The call being executed right now is ALREADY in `messages` (its assistant message is pushed
    // before `execute_tool_calls` runs), and it is excluded for free: its result has not been pushed
    // yet, so it matches no `ToolResult` and cannot count itself.
    let mut prior = 0usize;
    for (idx, m) in turn.iter().enumerate() {
        let Msg::Assistant { tool_calls, .. } = m else { continue };
        for tc in tool_calls {
            if tc.name != name || &tc.args != args {
                continue;
            }
            let same_result = turn[idx + 1..].iter().any(|r| {
                matches!(r, Msg::ToolResult { id, content } if id == &tc.id && content == output)
            });
            if same_result {
                prior += 1;
            }
        }
    }
    if prior == 0 {
        return None;
    }
    // BOUNDED BY CONSTRUCTION: one sentence appended to a result the model already receives, never a
    // message of its own — and it does NOT quote the earlier output back. That output is still in
    // the conversation a few messages up, so copying it would grow the context by the very bytes
    // being complained about.
    let already = if prior == 1 {
        "the one you already received".to_string()
    } else {
        format!("the {prior} you already received")
    };
    Some(format!(
        "{} This is call #{} of `{}` this turn, and its result is byte-identical to \
         {already}. Running it again cannot tell you anything new. Use the result you already have, \
         or take a different step.",
        REPEAT_NOTICE_MARKER,
        prior + 1,
        describe_tool_call(name, args),
    ))
}

/// The most a checkpoint may contribute to the next launch's INIT LINE.
///
/// The startup prompt is inlined into a shell command written to a PTY in CANONICAL MODE, where
/// Linux truncates a line past 4096 bytes — cut mid-string, unterminated `$'…'` quote, shell parked
/// at its `>` continuation prompt, agent never launched. `console/pty/launch.rs` documents having hit
/// exactly this once with a 4332-byte line.
///
/// Measured on the twitter-clone-test director: a 1511-byte kickoff plus a 2221-byte checkpoint, plus
/// the shell prefix and the ANSI-C escaping that doubles every quote and newline — comfortably over,
/// and the session would not start. The checkpoint is the part that grows without bound (one line per
/// tool call), so the checkpoint is the part that must be capped.
///
/// The FULL text still goes to `$BSC_CHECKPOINT_DOC`; only what is inlined is bounded, and the tail
/// names the file so the agent can read the rest with the tool it already has.
pub const CHECKPOINT_INLINE_BUDGET: usize = 900;

/// Bound `body` to [`CHECKPOINT_INLINE_BUDGET`], keeping the HEAD (the summary and the most recent
/// calls) and saying what was dropped. Cuts on a char boundary — a byte slice would panic on the
/// multi-byte characters this text is full of.
pub fn bound_for_inline(body: &str) -> String {
    if body.chars().count() <= CHECKPOINT_INLINE_BUDGET {
        return body.to_string();
    }
    let head: String = body.chars().take(CHECKPOINT_INLINE_BUDGET).collect();
    format!("{head}\n\n… (truncated — the full checkpoint is in $BSC_CHECKPOINT_DOC)\n")
}

pub fn mechanical_checkpoint(messages: &[Msg], steps_used: usize, max_steps: usize) -> String {
    let mut tools: Vec<String> = Vec::new();
    let mut last_text = String::new();
    for m in messages {
        if let Msg::Assistant { text, tool_calls } = m {
            if !text.trim().is_empty() {
                last_text = text.trim().to_string();
            }
            for tc in tool_calls {
                tools.push(describe_tool_call(&tc.name, &tc.args));
            }
        }
    }
    let mut out = format!(
        "# Checkpoint (automatic)\n\nThe previous turn used its whole {max_steps}-step budget \
({steps_used} steps) without reaching a final answer. This was written by the harness, not by the \
agent, so it is present whether or not the agent wrote one of its own.\n"
    );
    if !tools.is_empty() {
        out.push_str("\n## What ran\n");
        // The TAIL, not the head: what it was doing when it ran out is what the successor needs.
        let start = tools.len().saturating_sub(12);
        for t in &tools[start..] {
            out.push_str(&format!("- {t}\n"));
        }
        if start > 0 {
            out.push_str(&format!("- …and {start} earlier call(s)\n"));
        }
    }
    if !last_text.is_empty() {
        out.push_str("\n## What it last said\n");
        let tail: String = last_text.chars().rev().take(1200).collect::<String>().chars().rev().collect();
        out.push_str(&tail);
        out.push('\n');
    }
    out
}

/// Write `body` to `$BSC_CHECKPOINT_DOC` — the same doc `bsc-checkpoint` overwrites and the next
/// launch folds into its startup prompt (`composeStartupPrompt`), so this needs no new plumbing.
///
/// Best-effort and never fatal: an unset var (a bare `bsc-agent` run outside a pane) or an
/// unwritable path must not turn a completed turn into a failed one.
pub fn write_checkpoint_doc(body: &str) -> bool {
    let Ok(path) = std::env::var("BSC_CHECKPOINT_DOC") else { return false };
    if path.trim().is_empty() {
        return false;
    }
    let p = Path::new(&path);
    if let Some(dir) = p.parent() {
        let _ = std::fs::create_dir_all(dir);
    }
    std::fs::write(p, body).is_ok()
}

/// A tool executor: takes the model-supplied `args` and returns its result (or error).
pub type ToolFn = Box<dyn Fn(&Value) -> Result<String, String>>;

/// A tool the agent can run: its declaration (sent to the model) plus an executor.
pub struct Tool {
    pub def: ToolDef,
    pub run: ToolFn,
}


/// Resolve a model-emitted tool name to a real [`Tool`], tolerating the near-miss names local models
/// reach for instead of bouncing the call as "unknown tool". Three tiers, most-specific first:
///   1. exact name match (the normal path — Anthropic + a well-behaved local model);
///   2. normalized match (`file__create` → `file_create`, `File-Info` → `file_info`) — qwen3-coder
///      MCP-namespaces the file verbs with `__`, which otherwise never matches;
///   3. a small alias map for common synonyms (`create_file`/`str_replace`/`run`/`cat`/…).
///
/// An exact match always wins, so a real tool name is never remapped. Pure → unit-tested.
/// Tool-name aliases: a near-miss name a local model reaches for → the canonical tool. Table-driven
/// (#1846) so the synonyms live in data, not a match arm; `every_alias_targets_a_real_native_tool…`
/// asserts every target is a real native tool, so the table can't point at a renamed/removed tool.
const TOOL_ALIASES: &[(&str, &str)] = &[
    ("file_create", "write_file"), ("create_file", "write_file"), ("file_write", "write_file"),
    ("new_file", "write_file"), ("newfile", "write_file"), ("make_file", "write_file"), ("save_file", "write_file"),
    ("file_edit", "edit_file"), ("str_replace", "edit_file"), ("str_replace_editor", "edit_file"),
    ("replace_in_file", "edit_file"), ("apply_patch", "edit_file"), ("patch_file", "edit_file"),
    ("file_read", "read_file"), ("open_file", "read_file"), ("cat", "read_file"), ("view_file", "read_file"),
    ("file_list", "list_files"), ("list_dir", "list_files"), ("listdir", "list_files"),
    ("list_directory", "list_files"), ("ls", "list_files"),
    ("file_stat", "file_info"), ("stat", "file_info"),
    ("run", "bash"), ("run_command", "bash"), ("shell", "bash"), ("exec", "bash"),
    ("execute", "bash"), ("command", "bash"), ("run_shell", "bash"),
    ("search", "grep"), ("grep_search", "grep"), ("ripgrep", "grep"),
    ("glob_search", "glob"), ("find_files", "glob"),
    ("fetch", "webfetch"), ("http_get", "webfetch"), ("web_fetch", "webfetch"), ("curl", "webfetch"),
];

fn resolve_tool<'a>(name: &str, tools: &'a [Tool]) -> Option<&'a Tool> {
    if let Some(t) = tools.iter().find(|t| t.def.name == name) {
        return Some(t);
    }
    let n = normalize_tool_name(name);
    if let Some(t) = tools.iter().find(|t| normalize_tool_name(&t.def.name) == n) {
        return Some(t);
    }
    // Synonyms a model invents when it doesn't echo our exact verb (the TOOL_ALIASES table). Map to a
    // canonical tool name, then look it up in the live set (so an alias for an unavailable tool misses).
    let alias = TOOL_ALIASES.iter().find(|(a, _)| *a == n.as_str()).map(|(_, target)| *target)?;
    tools.iter().find(|t| t.def.name == alias)
}

/// How a tool call turned out — the three outcomes the pane must be able to tell apart.
///
/// Carried as a value rather than sniffed from the output text. `output.starts_with("error:")` would
/// be a guess: a `bash` tool whose COMMAND printed the word "error:" is a successful call, and a tool
/// that legitimately returns text beginning that way would be mislabelled forever.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ToolOutcome {
    Ok,
    /// The tool ran and failed, or the name resolved to nothing.
    Error,
    /// The permission gate refused it before it ran.
    Denied,
}

/// How many lines of a SUCCESSFUL result the pane shows.
///
/// A couple of lines, not one: one line proves the call returned but says almost nothing about WHAT,
/// and a director reading `ok · 4.2 KB` still has to fetch the thing to know whether it was the
/// answer it wanted. Three is enough for the shape of a JSON blob or the head of a table.
pub const RESULT_PREVIEW_LINES: usize = 3;

/// Per-line width for that preview — a single minified-JSON line is otherwise the whole terminal.
pub const RESULT_LINE_WIDTH: usize = 160;

/// The cap on an ERROR, which is shown in full below this length.
///
/// Generous on purpose: an error is the case this whole feature exists for, and truncating it to the
/// same width as a success preview would cut the one sentence that names the cause. Still capped, so
/// a tool that fails by printing a megabyte cannot take the pane with it.
pub const ERROR_PREVIEW_BUDGET: usize = 2000;

/// Render a tool's outcome for the pane — the counterpart to [`describe_tool_call`], which says what
/// was ATTEMPTED.
///
/// WHY THIS EXISTS. `execute_tool_calls` printed the call and then fed the result straight into the
/// message list, so nothing about the OUTCOME ever reached a human: not ok, not error, not size. The
/// twitter-clone-test director failed 7 of one turn's 18 tool calls with `error: unknown tool
/// 'bsc-fleet'` and the pane showed seven ordinary-looking `[tool]` lines. Nobody watching could see
/// that 39% of the turn was failing — the session looked exactly like one that was working.
///
/// A failure is shown IN FULL (up to [`ERROR_PREVIEW_BUDGET`]) while a success is a bounded preview,
/// because the two are not equally informative: a success is confirmed by its size and its first
/// lines, whereas an error is only useful if you can read the whole cause.
pub fn describe_tool_result(outcome: ToolOutcome, output: &str) -> String {
    let body = output.trim_end();
    match outcome {
        ToolOutcome::Denied | ToolOutcome::Error => {
            let label = if outcome == ToolOutcome::Denied { "DENIED" } else { "ERROR" };
            let text: String = body.chars().take(ERROR_PREVIEW_BUDGET).collect();
            let cut = body.chars().count() > ERROR_PREVIEW_BUDGET;
            let mut out = format!("  \u{2190} {label}: {text}");
            if cut {
                out.push_str(" …(truncated)");
            }
            out
        }
        ToolOutcome::Ok => {
            let bytes = output.len();
            // Say the SIZE even when the body is empty: a tool that legitimately returns nothing and
            // one whose output was swallowed look identical without it.
            let mut out = format!("  \u{2190} ok \u{b7} {}", human_bytes(bytes));
            if body.is_empty() {
                out.push_str(" (no output)");
                return out;
            }
            let total = body.lines().count();
            for line in body.lines().take(RESULT_PREVIEW_LINES) {
                let shown: String = line.chars().take(RESULT_LINE_WIDTH).collect();
                let cut = line.chars().count() > RESULT_LINE_WIDTH;
                out.push_str(&format!("\n     {shown}{}", if cut { "…" } else { "" }));
            }
            if total > RESULT_PREVIEW_LINES {
                out.push_str(&format!("\n     …(+{} more lines)", total - RESULT_PREVIEW_LINES));
            }
            out
        }
    }
}


/// How many CONSECUTIVE identical calls with identical results are tolerated before the next one is
/// refused rather than run. Two happen; a third is a loop.
pub const REPEAT_REFUSAL_AFTER: usize = 2;

/// How a refusal opens, so the run-length walk can recognise its own output. A refusal is this same
/// call declined; treating it as a NEW result would reset the count and let the tool run every other
/// time forever.
pub const REPEAT_REFUSAL_PREFIX: &str = "error: refused — you have already run";

/// How many times, immediately before now, this exact call was made AND returned the same bytes.
///
/// CONSECUTIVE is the whole point. `X X X` is the degenerate loop; `X Y X` is not, because `Y` may
/// have changed the world — `git status` after a write legitimately returns something new. Counting
/// backwards from the end and stopping at the first non-matching call keeps the rule safe without any
/// staleness heuristic.
///
/// The call being executed right now is already in `messages` (its assistant message is pushed before
/// `execute_tool_calls`), and excludes itself for free: it has no `ToolResult` yet.
fn consecutive_identical_calls(messages: &[Msg], name: &str, args: &Value) -> usize {
    let turn = messages
        .iter()
        .rposition(|m| matches!(m, Msg::User(_)))
        .map(|i| &messages[i + 1..])
        .unwrap_or(messages);
    // Walk backwards over (assistant, result) pairs.
    let mut n = 0usize;
    let mut last_result: Option<&str> = None;
    let mut i = turn.len();
    // SKIP THE CALL BEING MADE. At execution time the current assistant message is the LAST one and
    // has no result yet, so a walk that starts at the end sees `(ToolResult, Assistant)` and stops on
    // the first pair — reporting zero repeats forever. The unit tests missed this because they build
    // history without the in-flight call; the end-to-end one caught it (4 runs, not 2).
    if matches!(turn.last(), Some(Msg::Assistant { .. })) {
        i -= 1;
    }
    while i >= 2 {
        let (a, r) = (&turn[i - 2], &turn[i - 1]);
        let (Msg::Assistant { tool_calls, .. }, Msg::ToolResult { id, content }) = (a, r) else {
            break;
        };
        let Some(tc) = tool_calls.first() else { break };
        if tool_calls.len() != 1 || &tc.id != id || tc.name != name || &tc.args != args {
            break; // a DIFFERENT call ended the run
        }
        let body = result_body(content);
        // A REFUSAL CONTINUES THE RUN. It is this same call, declined — so it must not reset the
        // count, or the run-length collapses the moment we refuse and the tool starts running every
        // OTHER time. Measured before this line existed: run, run, refuse, RUN, refuse, run…
        if body.starts_with(REPEAT_REFUSAL_PREFIX) {
            n += 1;
            i -= 2;
            continue;
        }
        if last_result.is_some_and(|prev| prev != body) {
            break; // it returned something new — that repeat was productive
        }
        last_result = Some(body);
        n += 1;
        i -= 2;
    }
    n
}

/// The result handed back INSTEAD of running a call that is looping.
///
/// WHY A REFUSAL AND NOT A HINT. `repeat_notice` and `fold_repeated_calls` both fired on the live
/// director and neither broke the loop: it emitted BYTE-IDENTICAL reasoning text on three consecutive
/// steps. That is a fixed point — the same input producing the same output — and a hint cannot break
/// one, because the model that ignores it gets the same prompt again next step. Folding makes it
/// worse by design: removing the duplicate pair is exactly the context growth that would eventually
/// have perturbed the model.
///
/// Refusing changes the INPUT. The result now differs from the earlier ones, so the context genuinely
/// moves, folding cannot collapse it back, and the loop ends whether or not the model notices. The
/// tool does not run either, so a pointless command costs nothing.
fn repeat_refusal(name: &str, args: &Value, times: usize, prior: &str) -> String {
    let what = if prior.trim().is_empty() {
        "returned NO OUTPUT every time".to_string()
    } else {
        format!("returned exactly the same {} every time", human_bytes(prior.len()))
    };
    format!(
        "{REPEAT_REFUSAL_PREFIX} `{}` {times} times in a row this turn and it {what}. \
         It was NOT run again, because the answer cannot change. Do something DIFFERENT now: a \
         different command, a different path, or say what you have concluded and stop. If you were \
         looking for something and found nothing, that absence IS the answer — act on it.",
        describe_tool_call(name, args),
    )
}

/// The most recent result this exact call returned, so a refusal can say what it keeps getting.
fn last_result_for(messages: &[Msg], name: &str, args: &Value) -> Option<String> {
    let mut i = messages.len();
    while i >= 2 {
        if let (Msg::Assistant { tool_calls, .. }, Msg::ToolResult { id, content }) =
            (&messages[i - 2], &messages[i - 1])
        {
            if let Some(tc) = tool_calls.first() {
                if &tc.id == id && tc.name == name && &tc.args == args {
                    return Some(result_body(content).to_string());
                }
            }
        }
        i -= 1;
    }
    None
}

/// Execute every tool call the model made this step: resolve its (possibly near-miss) name, gate it
/// through `perms` (a denial is fed back AS the tool result so the model sees it and adapts rather than
/// crashing the loop), run the resolved tool, and push each result onto `messages`. Extracted from
/// `run_agent`'s step body (#2087).
fn execute_tool_calls(
    tool_calls: &[ToolCall],
    tools: &[Tool],
    perms: &Permissions,
    telemetry: &Telemetry,
    messages: &mut Vec<Msg>,
    session_path: Option<&Path>,
) {
    for tc in tool_calls {
        // Tolerant name resolution (#qwen): map a near-miss name (`file__create`) to the real tool
        // BEFORE gating/auditing, so perms + audit + the trace all use the canonical name.
        let resolved = resolve_tool(&tc.name, tools);
        let name = resolved.map(|t| t.def.name.as_str()).unwrap_or(tc.name.as_str());
        // The name AND what it is acting on. `[tool] bash` alone is the whole trace a local session
        // gets, and for a session whose surface is bash it distinguishes nothing.
        println!("[tool] {}", describe_tool_call(name, &tc.args));
        // A LOOP IS STOPPED, NOT ADVISED. See `repeat_refusal`.
        let looping = consecutive_identical_calls(messages, name, &tc.args);
        if looping >= REPEAT_REFUSAL_AFTER {
            let prior = last_result_for(messages, name, &tc.args).unwrap_or_default();
            let refusal = repeat_refusal(name, &tc.args, looping, &prior);
            println!("  \u{21bb} REFUSED \u{b7} {looping} identical calls in a row — not run again");
            messages.push(Msg::ToolResult { id: tc.id.clone(), content: refusal });
            continue;
        }
        let (outcome, output) = match perms.check(name, &tc.args) {
            Err(reason) => (ToolOutcome::Denied, reason),
            Ok(()) => {
                telemetry.audit(name, &tc.args); // one audit line per executed tool
                match resolved {
                    Some(tool) => match (tool.run)(&tc.args) {
                        Ok(out) => (ToolOutcome::Ok, out),
                        Err(e) => (ToolOutcome::Error, format!("error: {e}")),
                    },
                    None => (ToolOutcome::Error, format!("error: unknown tool '{}'", tc.name)),
                }
            }
        };
        // THE OUTCOME, not just the attempt. Without this the pane showed the call and nothing else,
        // so a failing turn was indistinguishable from a working one — see `describe_tool_result`.
        println!("{}", describe_tool_result(outcome, &output));
        // A LOOP IS SAID OUT LOUD — to the pane AND to the model. See `repeat_notice` for why it is
        // gated on the result being byte-identical rather than on the call alone.
        let output = match repeat_notice(messages, name, &tc.args, &output) {
            Some(notice) => {
                println!("  \u{21bb} repeated \u{b7} same result as an earlier call this turn");
                format!("{output}{notice}")
            }
            None => output,
        };
        messages.push(Msg::ToolResult { id: tc.id.clone(), content: output });
    }
    // PERSIST ONCE PER STEP, and deliberately HERE rather than inside the loop above.
    //
    // The durability problem: `save_conversation` ran only when a turn ENDED — a final answer, or the
    // step budget running out. A long agentic turn (twenty tool calls over several minutes, which is
    // what a director does) wrote nothing until it finished, so a kill mid-turn — an app relaunch, a
    // wake's `pty_kill`, a crash — lost every step of it, and the next launch's own save overwrote
    // the file. MEASURED after two app relaunches: the twitter-clone-test conversation held exactly
    // one turn, and everything before it was gone.
    //
    // Why not after each individual call: a step's assistant message carries N tool_calls, and the
    // providers require N matching tool results. Saving between them would persist an assistant
    // message with 3 calls and 1 result — a shape `--continue` would replay into a provider error.
    // Saving after the whole step keeps the conversation WELL-FORMED at every point it is written,
    // which is the property that makes a resume safe. Per-step is all the durability that was
    // missing anyway: twenty saves in a twenty-step turn instead of one.
    //
    // Cost: a full re-serialize per step. Measured against a real conversation, 13.8 KB for a
    // complete turn — a sub-millisecond write, against steps that each cost an LLM round trip in
    // seconds. Best-effort, like every other call: a failed write must never abort the turn.
    if let Some(p) = session_path {
        save_conversation(p, messages);
    }
}

// --- Runtime bridges -------------------------------------------------------
//
// A tool's [`ToolFn`] is **synchronous** (`Fn(&Value) -> Result<String, String>`) and runs inline
// on the tokio worker that drives the agent loop, but some tools need work that can't simply run
// there. There are two distinct sync→async bridges, deliberately kept as TWO helpers because they
// are NOT interchangeable:
//
// - [`run_off_runtime`] moves the work onto a **dedicated OS thread** and joins it. Used when the
//   work must run with NO ambient tokio runtime: `reqwest::blocking` panics if started inside a
//   runtime (`webfetch`), and the `task` sub-agent builds its OWN current-thread runtime on that
//   thread (a `block_on` would refuse to nest inside the parent runtime).
// - [`block_on_tool`] stays on the **current** (ambient) multi-thread runtime: `block_in_place` so
//   blocking the worker doesn't stall the whole runtime, then `block_on`s the future. Used when the
//   async work needs the live runtime (the MCP executor's shared client + I/O). It REQUIRES the
//   multi-thread runtime `bsc-agent` runs on — `block_in_place` panics on a current-thread runtime.

/// Run blocking work on a dedicated OS thread, away from the agent's tokio worker, and return its
/// result. See the module's "Runtime bridges" note for why this is separate from [`block_on_tool`].
pub fn run_off_runtime<T: Send>(f: impl FnOnce() -> Result<T, String> + Send) -> Result<T, String> {
    std::thread::scope(|s| s.spawn(f).join()).map_err(|_| "tool worker thread panicked".to_string())?
}

/// Block on `fut` from a sync tool body using the **current** multi-thread runtime
/// (`block_in_place` + `Handle::block_on`). See the module's "Runtime bridges" note; panics if the
/// ambient runtime is current-thread.
pub fn block_on_tool<F: std::future::Future>(fut: F) -> F::Output {
    tokio::task::block_in_place(|| tokio::runtime::Handle::current().block_on(fut))
}

/// Tokens held back from the context budget for the model's response + an incoming tool result — so a
/// compacted prompt still has room to answer. (`max_tokens` is 4096.) (#1831)
const COMPACT_RESERVE_TOKENS: usize = 4096 + 512;

/// The always-injected agent preamble (teaches a local model to run CLIs through `bash`, to use the
/// intent-named file tools, and to never refuse a command as "unsupported"). Prepended to the caller's
/// system prompt by [`run_agent`]. (#1078 P3)
const AGENT_INSTRUCTIONS: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/data/agent-instructions.md"));


/// The FIXED part of a turn's prompt: the system prompt PLUS the tool schemas that turn will carry.
///
/// Pure, and extracted rather than inlined, because the bug was in exactly this sum and an inline
/// version could only be tested through a live model call. The tool declarations are serialized into
/// every request and sit in the SAME window as the system prompt and the history; counting them as
/// zero is how the budget check passed while the request overflowed. `main.rs` already counted them
/// for its startup check, so the two paths disagreed — and the per-turn one runs on every step.
///
/// `handoff_turn` is charged NOTHING for tools because the handoff turn is offered an empty tool
/// list; charging it would shrink the history on the one turn that most needs it.
fn fixed_turn_tokens(
    turn_system: &str,
    tool_defs: &[ToolDef],
    env: &str,
    handoff_turn: bool,
) -> usize {
    let tools = if handoff_turn { 0 } else { llm::estimate_tool_tokens(tool_defs) };
    // The env block left the system prompt but not the WINDOW — it is appended after compaction, so
    // compaction has to be told about it or the budget silently loses that much room again.
    let env_tokens = env_message(env, handoff_turn).as_ref().map(msg_tokens).unwrap_or(0);
    estimate_tokens(turn_system) + tools + env_tokens
}

/// Approximate tokens a message contributes to the prompt.
fn msg_tokens(m: &Msg) -> usize {
    match m {
        Msg::User(s) => estimate_tokens(s),
        Msg::Assistant { text, tool_calls } => {
            estimate_tokens(text)
                + tool_calls
                    .iter()
                    .map(|tc| estimate_tokens(&tc.name) + estimate_tokens(&tc.args.to_string()))
                    .sum::<usize>()
        }
        Msg::ToolResult { content, .. } => estimate_tokens(content),
    }
}

/// The marker that opens a repeat notice, and the boundary the fold compares results at.
///
/// Shared deliberately: `repeat_notice` APPENDS this to the later duplicates, so a naive byte
/// comparison between the first result and a later one would never match — the very calls worth
/// folding are the ones carrying the note that says they repeat.
pub const REPEAT_NOTICE_MARKER: &str = "\n\n[repeated call]";

/// A tool result with any appended notice stripped — the part the tool actually returned.
fn result_body(content: &str) -> &str {
    match content.find(REPEAT_NOTICE_MARKER) {
        Some(i) => &content[..i],
        None => content,
    }
}

/// Fold runs of an IDENTICAL tool call whose result was identical into ONE copy carrying the count.
///
/// OBSERVED on the twitter-clone-test director: the same
/// `find . -type f -name "*.ts" | grep -v node_modules | …` ran at 20:30:46, :50, :53 and :57, and
/// `git status` repeatedly before that. Each repeat stored an assistant message AND a full copy of a
/// result the model already had — pure waste in the window that
/// `compaction-under-counts-the-prompt-so-it-aims-past-the-window` showed is the binding constraint.
///
/// ORTHOGONAL TO `compact_messages`, which elides BY AGE and drops the oldest wholesale. This removes
/// duplicates from anywhere in the turn while keeping one copy, so the model loses nothing it did not
/// already hold twice — strictly better than age-elision where it applies, and it runs first so the
/// space it frees is space compaction does not have to take from real history.
///
/// THE SAFETY RULE THAT KEEPS THE REQUEST VALID. A fold only ever drops an assistant message together
/// with its own result, and only when that message carries EXACTLY ONE tool call and NO text. Multiple
/// calls would leave siblings' results dangling, and text would silently discard something the model
/// said — both of which break the `tool_call` ↔ result pairing every provider requires, the same
/// invariant `compact_messages` protects when it refuses to begin on a dangling result.
///
/// A call whose result DIFFERED is never folded: it carried new information, and that is the same rule
/// `repeat_notice` uses to decide a repeat was worth remarking on.
pub(crate) fn fold_repeated_calls(messages: Vec<Msg>) -> (Vec<Msg>, usize) {
    // key -> (index of the surviving ToolResult in `out`, how many times it ran)
    let mut seen: std::collections::HashMap<(String, String, String), (usize, usize)> =
        std::collections::HashMap::new();
    let mut out: Vec<Msg> = Vec::with_capacity(messages.len());
    let mut folded = 0usize;
    let mut i = 0usize;
    while i < messages.len() {
        let foldable = match (&messages[i], messages.get(i + 1)) {
            (Msg::Assistant { text, tool_calls }, Some(Msg::ToolResult { id, content }))
                if text.trim().is_empty() && tool_calls.len() == 1 && &tool_calls[0].id == id =>
            {
                let tc = &tool_calls[0];
                Some((
                    (tc.name.clone(), tc.args.to_string(), result_body(content).to_string()),
                    content.clone(),
                ))
            }
            _ => None,
        };
        let Some((key, _)) = foldable else {
            out.push(messages[i].clone());
            i += 1;
            continue;
        };
        match seen.get_mut(&key) {
            Some((_, count)) => {
                *count += 1;
                folded += 1;
            }
            None => {
                out.push(messages[i].clone());
                // The surviving result keeps its ORIGINAL body; the count is stamped on afterwards,
                // once the whole pass knows it.
                out.push(Msg::ToolResult { id: key_id(&messages[i]), content: key.2.clone() });
                seen.insert(key, (out.len() - 1, 1));
            }
        }
        i += 2;
    }
    // Stamp the counts only now — a run's length is not known until the pass ends.
    for ((name, args, _), (idx, count)) in seen {
        if count < 2 {
            continue;
        }
        if let Some(Msg::ToolResult { content, .. }) = out.get_mut(idx) {
            let _ = (&name, &args);
            content.push_str(&format!(
                "\n\n[folded] This identical call ran {count} times this turn and returned exactly \
                 this every time. The repeats are omitted from the history above; running it again \
                 will return this same result."
            ));
        }
    }
    (out, folded)
}

/// The tool-call id of a single-call assistant message. Only reached for messages `fold_repeated_calls`
/// has already established have exactly one.
fn key_id(m: &Msg) -> String {
    match m {
        Msg::Assistant { tool_calls, .. } => {
            tool_calls.first().map(|t| t.id.clone()).unwrap_or_default()
        }
        _ => String::new(),
    }
}

/// Compact a conversation to fit a context `budget` (#1831): keep the system prompt (counted via
/// `system_tokens`, separate from `messages`), the first user message (the task), and the most-recent
/// messages that fit; elide the middle, replacing it with a marker. Drops only at safe boundaries — a
/// dangling tool-result whose assistant call was elided is removed too — so the OpenAI/Ollama
/// tool_call↔result pairing stays valid. Returns the (possibly) compacted messages + whether it
/// changed anything. Pure → unit-tested. (Elision, not summarization — a summarize pass is a future
/// refinement.)
pub(crate) fn compact_messages(
    system_tokens: usize,
    messages: Vec<Msg>,
    budget: usize,
    reserve: usize,
) -> (Vec<Msg>, bool) {
    let usable = budget.saturating_sub(reserve);
    let total: usize = system_tokens + messages.iter().map(msg_tokens).sum::<usize>();
    if total <= usable || messages.len() <= 2 {
        return (messages, false);
    }
    // Anchor the first user message (the task), if the head is one.
    let mut head: Vec<Msg> = Vec::new();
    if matches!(messages.first(), Some(Msg::User(_))) {
        head.push(messages[0].clone());
    }
    let marker = Msg::User("[earlier conversation elided to fit the context window]".to_string());
    let head_tokens: usize = head.iter().map(msg_tokens).sum::<usize>() + msg_tokens(&marker);
    let mut budget_left = usable.saturating_sub(system_tokens + head_tokens);
    // Keep the most-recent messages that fit (scanning from the end, after the anchored head).
    let mut kept_rev: Vec<Msg> = Vec::new();
    for m in messages[head.len()..].iter().rev() {
        let t = msg_tokens(m);
        if t > budget_left {
            break;
        }
        budget_left -= t;
        kept_rev.push(m.clone());
    }
    kept_rev.reverse();
    // The kept region must not begin with a dangling tool-result (its assistant call was elided).
    while matches!(kept_rev.first(), Some(Msg::ToolResult { .. })) {
        kept_rev.remove(0);
    }
    let mut out = head;
    out.push(marker);
    out.extend(kept_rev);
    (out, true)
}

/// Build a turn's system prompt: the fixed agent preamble ([`AGENT_INSTRUCTIONS`]) + the caller's
/// `system`. Pure → unit-tested.
///
/// #3278 removed the per-turn TODO-checklist fold (the local-first consolidation onto `bsc plan`
/// scrapped the todo store). #3279 reintroduces a per-turn injection — the worker's own open issues
/// from a stream-scoped `bsc plan mine` — and will re-add the block param + its compaction-survival
/// test then, together with the source, so no always-empty argument sits here in the meantime.
/// The facts a session needs about ITSELF, gathered per turn.
///
/// Every field is `Option`: a value with nothing to say is ABSENT from the rendered block rather than
/// present and empty. `git: (none)` teaches a model nothing, and an empty write scope read as a line
/// would say "no restriction" — the opposite of what an empty `BSC_SCOPE_GLOBS` means to the gate.
#[derive(Debug, Default, Clone, PartialEq)]
pub struct EnvFacts {
    pub cwd: Option<String>,
    /// `(branch, one-line state)` — the state is whatever was cheap to learn.
    pub git: Option<(String, String)>,
    pub platform: Option<String>,
    pub date: Option<String>,
    /// The pane id, role and stream this session runs as.
    pub session: Option<String>,
    /// `provider · model`.
    pub model: Option<String>,
    /// The globs this session may write, exactly as the gate has them.
    pub write_scope: Option<String>,
}

/// Gather the session's own facts. Called EVERY TURN — see the cost note below.
///
/// ## Why per turn and not once at launch
///
/// `cwd` changes the moment the agent `cd`s, and the branch changes the moment it checks one out —
/// which is most of what a worker does. A block captured at launch would go on confidently stating
/// the old branch, and a weak model believes what it is told: a stale fact is worse than an absent
/// one, because an absent one sends it to look.
///
/// ## What it costs, measured rather than assumed
///
/// Three git subprocesses on this repo, timed: `rev-parse --abbrev-ref` 0.00 s,
/// `status --porcelain --untracked-files=no` 0.00 s, `rev-list --count` 0.00 s — against a turn that
/// costs an LLM round trip in seconds. `--untracked-files=no` is not incidental: it stops git walking
/// untracked trees, which in this repo means a 20 GB `target/`, and "dirty" here means TRACKED
/// modifications anyway (the same definition `promote-plan` uses).
///
/// Every probe fails SOFT. A cwd that cannot be read, a directory that is not a repo, a git that is
/// not installed — each leaves its field `None` and the block simply omits that line. This runs
/// before every turn and must never be the reason a turn does not happen.
pub fn gather_env_facts(cwd: &Path) -> EnvFacts {
    let git = |args: &[&str]| -> Option<String> {
        let out = std::process::Command::new("git").current_dir(cwd).args(args).output().ok()?;
        out.status.success().then(|| String::from_utf8_lossy(&out.stdout).trim().to_string())
    };
    let branch = git(&["rev-parse", "--abbrev-ref", "HEAD"]).filter(|b| !b.is_empty());
    let git_facts = branch.map(|b| {
        let mut state = Vec::new();
        if let Some(st) = git(&["status", "--porcelain", "--untracked-files=no"]) {
            let n = st.lines().filter(|l| !l.trim().is_empty()).count();
            state.push(if n == 0 { "clean".to_string() } else { format!("{n} modified") });
        }
        // Ahead of the integration branch, which is the number a worker acts on. Absent when there is
        // no `develop` to compare against, rather than reported as zero.
        if let Some(n) = git(&["rev-list", "--count", "develop..HEAD"]).filter(|n| n != "0") {
            state.push(format!("{n} ahead of develop"));
        }
        (b, state.join(" · "))
    });

    let var = |k: &str| std::env::var(k).ok().map(|v| v.trim().to_string()).filter(|v| !v.is_empty());

    // The session's identity: who this agent IS. A worker had no way to know it was one.
    let session = {
        let mut bits = Vec::new();
        if let Some(p) = var("BSC_AUDIT_PANE") {
            bits.push(format!("pane {p}"));
        }
        if let Some(st) = var("BSC_STREAM") {
            bits.push(format!("stream {st}"));
        }
        (!bits.is_empty()).then(|| bits.join(" · "))
    };

    let model = {
        let provider = var("BSC_AGENT_PROVIDER");
        let m = var("BSC_AGENT_MODEL");
        match (provider, m) {
            (Some(p), Some(m)) => Some(format!("{p} · {m}")),
            (Some(p), None) => Some(p),
            (None, Some(m)) => Some(m),
            (None, None) => None,
        }
    };

    EnvFacts {
        cwd: Some(cwd.to_string_lossy().into_owned()).filter(|c| !c.is_empty()),
        git: git_facts,
        platform: Some(format!("{} · {}", std::env::consts::OS, shell_name())),
        // The DAY only. A model that knows the date can reason about staleness ("this issue is from
        // March"); a timestamp to the second is noise it will try to use.
        date: Some(bsc_util::epoch_ms_to_iso8601(bsc_util::now_ms()).chars().take(10).collect()),
        session,
        model,
        // Exactly what the gate has, with the sentinel spelled out rather than shown raw: a worker
        // that reads `__bsc_deny_all__` learns nothing, and it is the one value whose meaning a model
        // cannot guess.
        write_scope: var("BSC_SCOPE_GLOBS").map(|g| {
            if g.trim() == "__bsc_deny_all__" { "NOTHING — this role writes no code".to_string() } else { g }
        }),
    }
}

/// The shell the `bash` tool actually runs, for the platform line.
fn shell_name() -> String {
    std::env::var("BSC_AGENT_BASH")
        .ok()
        .and_then(|p| Path::new(&p).file_name().map(|f| f.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "bash".to_string())
}

/// Render [`EnvFacts`] as the block a model reads.
///
/// ## Why this exists
///
/// A `bsc-agent` system prompt was four things — the tool preamble, the CLAUDE.md chain, skills, and
/// the CLI inventory — and NONE of them says where the session is. Nothing stated the working
/// directory, the platform, the date, the git branch, the session's own role or stream, the model it
/// runs as, or which paths it may write. A strong model infers to run `pwd`; a 9B local one does not,
/// and was never told. Reported directly: "I navigated to the root directory of this application and
/// the local model wasn't aware of its context."
///
/// ## Why it is a TABLE and not prose
///
/// It lands after ~13-54k tokens of markdown documents. Prose would be more of the same and would
/// disappear into it; aligned `label  value` lines are the one shape that still reads as a lookup at
/// that depth. Short labels, one fact per line, no sentences.
///
/// ## Two lines that are not obvious
///
/// `session` — a worker has no idea it IS a worker, which stream it owns, or that it files to a
/// director; that identity lived only in a kickoff prompt that scrolls away.
///
/// `write scope` — `BSC_SCOPE_GLOBS` is enforced by a PreToolUse hook and was never disclosed, so a
/// worker discovered its boundary only by being denied, which a weak model reads as a broken tool
/// rather than a rule. Stating it widens nothing: the gate is unchanged, and a rule you can see is
/// one you can follow.
pub fn render_env_block(f: &EnvFacts) -> String {
    let mut rows: Vec<(&str, String)> = Vec::new();
    if let Some(v) = &f.cwd {
        rows.push(("cwd", format!("{v}   — `bash` starts every command here")));
    }
    if let Some((branch, state)) = &f.git {
        rows.push(("git", if state.is_empty() { branch.clone() } else { format!("{branch} · {state}") }));
    }
    if let Some(v) = &f.platform {
        rows.push(("platform", v.clone()));
    }
    if let Some(v) = &f.date {
        rows.push(("date", v.clone()));
    }
    if let Some(v) = &f.session {
        rows.push(("session", v.clone()));
    }
    if let Some(v) = &f.model {
        rows.push(("model", v.clone()));
    }
    if let Some(v) = &f.write_scope {
        rows.push(("write scope", format!("{v}   — writes outside this are REFUSED by the gate")));
    }
    if rows.is_empty() {
        return String::new();
    }
    let mut out = String::from("# Environment

These are facts about THIS session, refreshed every turn. Trust them over anything older in
this context.

");
    for (k, v) in rows {
        out.push_str(&format!("{k:<12}  {v}
"));
    }
    out
}

/// Build a turn's STABLE system prompt: the fixed preamble, the caller's `system`, and the
/// assigned-issues block. Everything here is expected to be byte-identical from one turn to the next.
///
/// THE ENVIRONMENT BLOCK USED TO END UP HERE, AND IT COST 41 SECONDS A STEP. It is refreshed every
/// turn — it carries `cwd` and the git branch AND working-tree state, which churns every time the
/// worker writes a file — and the system prompt sits in front of the entire conversation. So a value
/// that changed every turn sat immediately ahead of ~52,000 tokens of history and invalidated the KV
/// cache for all of it.
///
/// MEASURED from llama-server's own slot log (task 61186): of a 58,648-token prompt, 6,424 tokens
/// were reused and 52,220 re-processed, taking 41.15 s BEFORE the first generated token — and
/// `cached n_tokens - n_tokens` was a constant 6,424 across all 23 batch lines, which is exactly the
/// preamble plus `system` plus the issue block. The boundary was where the env block began.
///
/// It now rides at the TAIL of the messages instead (see [`env_message`]), which is strictly better on
/// BOTH axes. The original placement was chosen for recency — "the freshest thing furthest from the
/// stalest" — and the tail is more recent still, while leaving the prefix stable.
fn compose_turn_system(system: &str, block: Option<&str>) -> String {
    let mut out = format!("{AGENT_INSTRUCTIONS}\n\n{system}");
    if let Some(b) = block.filter(|b| !b.trim().is_empty()) {
        out.push_str(&format!("\n\n{b}"));
    }
    out
}

/// The per-turn environment facts, as the LAST message of the request.
///
/// `None` when there is nothing to say, or on the handoff turn — which is summarizing the
/// conversation, not acting in the environment, and is deliberately given the whole window for
/// history (it is offered no tools either).
///
/// Appended to the REQUEST only, never to the persisted conversation: turn N's env must not become
/// part of turn N+1's prefix, or the churn simply moves one message later and voids the cache again.
fn env_message(env: &str, handoff_turn: bool) -> Option<Msg> {
    (!handoff_turn && !env.trim().is_empty()).then(|| Msg::User(env.to_string()))
}

/// What a resumed session is told, in place of its kickoff being stated a second time.
///
/// The kickoff is still in the conversation above — it is not repeated here, because repeating it is
/// the whole defect this replaces.
pub const RESUME_PROMPT: &str = "You are RESUMING the task already stated above — this is the same \
run continuing, not a new one. Do not start over and do not redo work that is already done. Read \
back over what you did, establish what is finished and what is not, and continue from there. If \
everything is done, say so instead of doing it again.";

/// The user turn that opens a launch: the task itself, or — on a resume that would merely restate it —
/// a continuation instruction.
///
/// WHY THIS EXISTS. `run_agent` pushed `Msg::User(user)` unconditionally after `prior`, so every
/// relaunch loaded the whole conversation AND re-stated the original kickoff. MEASURED on the
/// twitter-clone-test worker's own persisted conversation: FOUR identical
/// "Build the REST API: auth, posts, likes, feed" user turns across 56 messages. The model read
/// "build the API" → [I built it] → "build the API" → [I built it] → "build the API", and an
/// autoregressive model completes that pattern by building it again — which is why `src/routes/Auth.ts`
/// was written at exactly 2031 bytes before two separate deaths, and why the worker reported 3/3
/// issues still open after four launches of real work.
///
/// It is also why this began when history did: before resume, each launch was a fresh conversation
/// with the task stated ONCE, so there was no repetition to pattern-match on.
///
/// SUPPRESSION IS FOR AN EXACT REPEAT ONLY. A relaunch may legitimately carry a NEW instruction — a
/// director re-tasking a worker — and dropping that would be a worse bug than the one being fixed.
/// So the task is compared against the user turns already present, and anything new is delivered
/// unchanged.
pub(crate) fn resume_turn(prior: &[Msg], user: &str) -> Msg {
    let already_stated = prior
        .iter()
        .any(|m| matches!(m, Msg::User(u) if u.trim() == user.trim() && !u.trim().is_empty()));
    if already_stated {
        Msg::User(RESUME_PROMPT.to_string())
    } else {
        Msg::User(user.to_string())
    }
}

/// Run the agent loop: build a [`Turn`] from the conversation + tools, ask the
/// provider, and while it returns tool calls, execute them, append the results, and
/// continue — until the provider answers with no tool calls (final text) or the
/// step budget runs out. Assistant text and a `[tool] <name>` trace are printed as
/// they happen (the binary runs inside the PTY).
///
/// `interactive` keeps the session alive like Claude Code's REPL: after a task settles (a final
/// answer or an exhausted budget) it reads the next user turn from **stdin** and continues the
/// conversation, persisting after each turn, until stdin reaches EOF (the pane closed). Without it
/// the loop runs the one task and returns — the right behavior for a sub-agent / one-shot call. The
/// interactive path is what makes the planner / director usable on bsc-agent: the user keeps steering
/// instead of the process exiting (and ending the PTY) after the first response.
#[allow(clippy::too_many_arguments)] // the agent entrypoint legitimately takes the full session config
pub async fn run_agent<P: LlmProvider>(
    provider: &P,
    api_key: &str,
    model: &str,
    system: &str,
    user: &str,
    tools: &[Tool],
    perms: &Permissions,
    telemetry: &Telemetry,
    // Prior conversation to resume (empty = fresh), and where to persist the conversation
    // afterward so a later --continue can resume it (None = don't persist).
    prior: &[Msg],
    session_path: Option<&Path>,
    max_steps: usize,
    interactive: bool,
) -> Result<String, String> {
    // SHOW WHAT WAS RESUMED. The model gets `prior` either way; without this the pane does not, and a
    // resumed session was visually identical to a fresh one because the init line clears the screen.
    if interactive && !prior.is_empty() {
        print!("{}", replay_prior(prior));
    }
    let mut messages: Vec<Msg> = prior.to_vec();
    messages.push(resume_turn(prior, user));
    let tool_defs: Vec<ToolDef> = tools.iter().map(|t| t.def.clone()).collect();
    let mut last_text = String::new();

    // Context-budget compaction (#1831): the model's usable window in tokens, set by the app from the
    // provider's num_ctx ($BSC_AGENT_CONTEXT_BUDGET; defaults high for hosted models, so a no-op there).
    // The fixed system prompt + a response reserve are subtracted; older turns are elided to fit.
    let context_budget: usize = std::env::var("BSC_AGENT_CONTEXT_BUDGET")
        .ok()
        .and_then(|s| s.trim().parse().ok())
        .unwrap_or(200_000);
    let mut announced_compaction = false;
    let mut announced_fold = false;

    // Outer loop = one iteration per USER turn. One-shot (non-interactive) runs it exactly once; in
    // interactive mode each pass handles a user message, then blocks for the next on stdin.
    loop {
        let mut answered = false;
        // Was the handoff injected this turn? A turn that took one is INCOMPLETE even when the model
        // then "answers" — the answer IS the handoff, not the work. Without this the success path
        // skipped the checkpoint entirely, so the case where the mechanism worked was the case where
        // the successor got nothing (`a_successful_handoff_still_leaves_a_checkpoint_on_disk`).
        let mut handoff_taken = false;
        // How many steps this turn actually consumed — the checkpoint reports it, and the handoff
        // boundary is measured from it rather than from `step`, which is the loop's own counter.
        let mut steps_used = 0usize;
        for step in 0..max_steps {
            steps_used = step + 1;
            // #3279: fold the worker's OWN open issues (stream-scoped `$BSC_STREAM`) into the system
            // prompt EVERY turn. It rides in `system` (never in `messages`), so the compaction below —
            // which only touches `messages` — can't elide it; it's re-rendered from plan.db each turn.
            // Best-effort + None-safe (no plan.db / no stream / no open issues ⇒ nothing injected).
            let assigned = plandb::scope::render_assigned_from_env();
            // WHERE AND WHO, refreshed every turn. Gathered here rather than at launch because `cwd`
            // and the branch both change under the agent's own feet — see `gather_env_facts`.
            let env_block = render_env_block(&gather_env_facts(
                &std::env::current_dir().unwrap_or_default(),
            ));
            let turn_system = compose_turn_system(system, assigned.as_deref());
            // THE HANDOFF TURN CARRIES NO TOOLS, so it must not be charged for them — it is the one
            // turn that legitimately has the whole window for history. Computed here rather than at
            // the `Turn` below because the budget math needs it first; `messages` is not touched in
            // between (compaction clones it).
            let handoff_turn = matches!(messages.last(), Some(Msg::User(u)) if u == HANDOFF_PROMPT);
            // COUNT THE TOOLS. They ride in the SAME window as the system prompt and the history, on
            // every turn, and they were counted as ZERO — exactly what `crates/llm` warns about:
            // "Excluding them is how a budget check passes and the request still overflows."
            // `main.rs` already counts them for the STARTUP check, so the two paths disagreed, and the
            // one that disagreed is the one that runs on every step. MEASURED on the twitter-clone-test
            // fleet: the 32 tool schemas are ~4,580 tokens, and compaction aimed that far past a
            // 65,536-token window — so ollama truncated to half the window and kept the TAIL, throwing
            // away the head where the project spec lives.
            let system_tokens =
                fixed_turn_tokens(&turn_system, &tool_defs, &env_block, handoff_turn);
            // Compact older turns to fit the model's context window (#1831) — a clone for THIS request;
            // the persisted `messages` keep the full history (a later `--continue` loses nothing it
            // wouldn't have had to drop anyway).
            // FOLD BEFORE COMPACTING. Duplicates are the cheapest thing in the window to give up —
            // the model already holds the information — so removing them first is space compaction
            // does not then have to take out of real history.
            let (folded_messages, folded) = fold_repeated_calls(messages.clone());
            if folded > 0 && !announced_fold {
                eprintln!(
                    "\x1b[2m· folded {folded} repeated tool call(s) out of this turn's history\x1b[0m"
                );
                announced_fold = true;
            }
            let (turn_messages, did_compact) =
                compact_messages(system_tokens, folded_messages, context_budget, COMPACT_RESERVE_TOKENS);
            // THE ENV FACTS GO LAST, BEHIND THE HISTORY — see `compose_turn_system` for the 41-second
            // measurement that moved them here. Appended AFTER compaction so the stable prefix this
            // turn presents is byte-identical to last turn's whenever only the environment changed.
            let mut turn_messages = turn_messages;
            turn_messages.extend(env_message(&env_block, handoff_turn));
            if did_compact && !announced_compaction {
                eprintln!("\x1b[2m· compacted older turns to fit the ~{context_budget}-token context window\x1b[0m");
                announced_compaction = true;
            }
            // THE HANDOFF TURN GETS NO TOOLS. Asked to "write a handoff", a model holding a
            // `write_file` tool writes a FILE — a reasonable reading, and useless here, because the
            // checkpoint is assembled from the CONVERSATION, not from the disk. Removing the tools
            // makes that impossible rather than discouraged, so the only thing it can do is reply
            // with text. Programmatic, not asked for — the same principle as the handoff itself.
            let turn = Turn {
                system: turn_system,
                messages: turn_messages,
                tools: if handoff_turn { Vec::new() } else { tool_defs.clone() },
                model: model.to_string(),
                max_tokens: 4096,
            };
            // Per-turn heartbeat to the PTY (stderr): the request is non-streaming, so without this
            // the pane shows nothing while the model thinks — indistinguishable from a hang. Dim, so
            // it doesn't clutter the real output.
            eprintln!("\x1b[2m· thinking (step {}/{max_steps})…\x1b[0m", step + 1);
            // Stream assistant text to the PTY token-by-token as it's generated (#1832), instead of
            // dumping the whole answer after the turn settles.
            let mut streamed_any = false;
            let mut result = turn_streaming_with_retry(
                provider,
                &turn,
                api_key,
                Duration::from_millis(500),
                &last_retry_after,
                &mut |chunk| {
                    use std::io::Write;
                    print!("{chunk}");
                    let _ = std::io::stdout().flush();
                    streamed_any = true;
                },
            )
            .await?;
            // Fallback for local models (#1078): some — notably qwen via Ollama — emit tool calls as
            // TEXT (`<tool_call>{…}</tool_call>` / `<function=name>…</function>`) instead of the
            // structured `tool_calls` field, which the OpenAI-compat endpoint then doesn't convert.
            // When the structured field is empty, recover any call from the text so it still runs (and
            // strip the raw syntax from what we display).
            if result.tool_calls.is_empty() {
                if let Some((text, calls)) = llm::recover_text_calls(&result.text) {
                    result.text = text;
                    result.tool_calls = calls;
                }
            }
            // Record every assistant turn to the transcript (cost accounting reads its usage).
            telemetry.record_assistant(model, &result.usage);
            // The text was streamed live above (#1832); just terminate the line. (Nothing to print for
            // a pure tool-call turn that produced no text.)
            if streamed_any {
                println!();
            }
            if result.tool_calls.is_empty() {
                // Final answer for this user turn: record it, persist, stop stepping.
                messages.push(Msg::Assistant { text: result.text.clone(), tool_calls: vec![] });
                if let Some(p) = session_path {
                    save_conversation(p, &messages);
                }
                last_text = result.text.clone();
                answered = true;
                break;
            }
            messages.push(Msg::Assistant {
                text: result.text.clone(),
                tool_calls: result.tool_calls.clone(),
            });
            execute_tool_calls(&result.tool_calls, tools, perms, telemetry, &mut messages, session_path);
            // THE HANDOFF IS TAKEN, NOT ASKED FOR. With `HANDOFF_RESERVE` steps left the harness
            // injects `HANDOFF_PROMPT` as the next user turn, so the model spends its last steps
            // landing the plane instead of starting something it cannot finish. Fires once — the
            // `== ` is deliberate, not `>=`, so a long turn cannot re-inject it every step.
            if steps_used + HANDOFF_RESERVE == max_steps {
                handoff_taken = true;
                messages.push(Msg::User(HANDOFF_PROMPT.to_string()));
                eprintln!("\x1b[2m· step budget nearly spent — asking for a handoff\x1b[0m");
            }
        }

        // The agentic loop for this user turn ended. If it ran out of steps without a final answer,
        // persist what we have; one-shot surfaces the budget error, interactive notes it and waits.
        if !answered || handoff_taken {
            if let Some(p) = session_path {
                save_conversation(p, &messages);
            }
            // THE FLOOR. Derived from the conversation, so it exists whether or not the model
            // honoured `HANDOFF_PROMPT` — which is the whole point: the model that most needs a
            // checkpoint is the least likely to write one, and a missing one is invisible.
            // The agent's OWN handoff, when it wrote one, is already inside this (it is the last
            // assistant text), so the two compose rather than compete.
            // BOUNDED. This doc is inlined verbatim into the next launch's init line, which a PTY
            // in canonical mode truncates past 4096 bytes — and a truncated `$'…'` leaves the shell
            // at its `>` prompt with the agent never launched. A checkpoint is a SUMMARY; the full
            // transcript is already in `$BSC_AGENT_SESSION/conversation.json`, which `--continue`
            // replays, so nothing is lost by keeping this short.
            let wrote = write_checkpoint_doc(&bound_for_inline(&mechanical_checkpoint(
                &messages, steps_used, max_steps,
            )));
            if answered {
                // The handoff landed: the model spent its reserve writing one, and it is now on disk.
                // NOT an error — the turn produced exactly what was asked of it — so one-shot falls
                // through to the normal `Ok` return below and the next launch resumes from the doc.
                eprintln!(
                    "\x1b[2m· handed off at step {steps_used}/{max_steps}{}\x1b[0m",
                    if wrote { " — checkpoint written" } else { " — NO $BSC_CHECKPOINT_DOC to write to" }
                );
            } else if !interactive {
                telemetry.finish();
                // Naming the checkpoint matters: a one-shot worker that hits the budget is a PAUSE
                // with a handoff on disk, not lost work — and the caller cannot tell which unless
                // this says so.
                return Err(if wrote {
                    format!(
                        "agent did not finish within {max_steps} steps — a checkpoint was written to \
                         $BSC_CHECKPOINT_DOC and the next launch resumes from it"
                    )
                } else {
                    format!("agent did not finish within {max_steps} steps (no $BSC_CHECKPOINT_DOC to check point to)")
                });
            }
            if !answered {
                eprintln!("\x1b[2m· (reached the {max_steps}-step budget for this turn — add direction to continue)\x1b[0m");
            }
        }

        // One-shot mode returns the final answer (the historical contract). Interactive mode waits
        // for the next user message and loops; EOF on stdin (pane closed / Ctrl-D) ends the session.
        if !interactive {
            telemetry.finish();
            return Ok(last_text);
        }
        match read_next_user_turn().await {
            Some(next) => messages.push(Msg::User(next)),
            None => {
                telemetry.finish();
                return Ok(last_text);
            }
        }
    }
}

/// Block (off the async worker) for the next user turn from stdin, echoing a prompt first. Returns
/// `None` on EOF (the PTY closed) so the caller ends the session; skips blank lines so a stray Enter
/// doesn't submit an empty turn. The PTY is in canonical mode, so the terminal line-edits + echoes
/// the user's typing — they see what they enter.
async fn read_next_user_turn() -> Option<String> {
    use std::io::{BufRead, Write};
    loop {
        // A visible, distinct prompt so the user knows the agent is waiting for them (not hung).
        eprint!("\n\x1b[1;36m› \x1b[0m");
        let _ = std::io::stderr().flush();
        let line = tokio::task::spawn_blocking(|| {
            let mut s = String::new();
            match std::io::stdin().lock().read_line(&mut s) {
                Ok(0) | Err(_) => None, // EOF or read error
                Ok(_) => Some(s),
            }
        })
        .await
        .ok()
        .flatten()?;
        let trimmed = line.trim();
        if !trimmed.is_empty() {
            return Some(trimmed.to_string());
        }
        // Blank line — re-prompt rather than submitting an empty turn.
    }
}

/// How many times a *transient* provider error is retried before the loop gives up.
const MAX_TURN_RETRIES: usize = 3;


/// The longest a single backoff may last, however long the server asks for.
///
/// A provider is entitled to say "come back in an hour", and some do. Honouring that literally would
/// park a worker inside a step the fleet believes is running. With [`MAX_TURN_RETRIES`] at 3 the
/// worst total wait is three of these, so this bounds one stalled turn at ~3 minutes rather than at
/// the provider's discretion.
const RETRY_AFTER_CAP: Duration = Duration::from_secs(60);

/// The last `Retry-After` a provider sent on a RETRYABLE response, in seconds.
///
/// WHY A CELL AND NOT A RETURN VALUE. `LlmProvider::turn_streaming` returns
/// `Result<TurnResult, String>`, so the headers `crates/llm` now parses cannot ride back with the
/// error — carrying them would mean a metered result across four providers and every caller.
/// `llm::ratelimit`'s observer exists precisely to cover that path: it fires on EVERY response,
/// success or error, and the error is where `Retry-After` lives.
static LAST_RETRY_AFTER: std::sync::Mutex<Option<Duration>> = std::sync::Mutex::new(None);

/// Records the server's own wait instruction, and FORWARDS to whatever observer was installed before.
///
/// Forwarding is not politeness. `llm::ratelimit::install_rate_limit_log` puts the headroom recorder
/// in the one observer slot, so replacing it would silently stop `bsc mem headroom` recording while
/// looking like it worked. Installing this COMPOSES rather than displaces.
struct RetryAfterCapture {
    inner: Option<std::sync::Arc<dyn llm::ratelimit::RateLimitObserver>>,
}

impl llm::ratelimit::RateLimitObserver for RetryAfterCapture {
    fn observe(&self, url: &str, status: u16, limits: &llm::ratelimit::RateLimits) {
        // Only a RETRYABLE status carries an instruction worth obeying. A 200 that happens to carry
        // `Retry-After` is not telling us to wait before the next turn, and treating it as one would
        // slow a perfectly healthy run.
        let hint = if status == 429 || status >= 500 {
            limits.retry_after_secs.map(Duration::from_secs)
        } else {
            None
        };
        if let Ok(mut slot) = LAST_RETRY_AFTER.lock() {
            *slot = hint;
        }
        if let Some(inner) = &self.inner {
            inner.observe(url, status, limits);
        }
    }
}

/// Put the capture in front of whatever observer is already installed.
///
/// Call AFTER `llm::ratelimit::install_rate_limit_log`, so the headroom recorder becomes this one's
/// inner and both run.
pub(crate) fn install_retry_after_capture() {
    let prev = llm::ratelimit::set_rate_limit_observer(None);
    llm::ratelimit::set_rate_limit_observer(Some(std::sync::Arc::new(RetryAfterCapture { inner: prev })));
}

/// What the last retryable response told us to wait, if anything.
///
/// CONSUMES the hint. A stale instruction from an earlier turn must not delay a fresh failure that
/// the server did not ask us to wait for — the observer refills it on the next response.
fn last_retry_after() -> Option<Duration> {
    LAST_RETRY_AFTER.lock().ok().and_then(|mut slot| slot.take())
}


/// How long to wait before the next attempt.
///
/// THE SERVER'S INSTRUCTION WINS. When a retryable response carried `Retry-After`, that is what the
/// provider asked for and guessing a shorter local delay is how a fleet turns one rate limit into
/// several. The local schedule is the FALLBACK for a provider that said nothing.
///
/// Capped by [`RETRY_AFTER_CAP`], then jittered. Pure, so every branch is testable.
fn next_backoff(attempt: u32, base: Duration, hint: Option<Duration>, entropy: u64) -> Duration {
    let chosen = match hint {
        Some(d) => d.min(RETRY_AFTER_CAP),
        None => base * (1u32 << attempt), // base, 2x, 4x
    };
    jittered(chosen, entropy)
}

/// Nanosecond-resolution entropy for [`jittered`].
///
/// Not cryptographic and does not need to be: the only job is that two processes hitting the same
/// rate limit compute different delays, and two wall clocks are not synchronised to the nanosecond.
fn now_entropy() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.subsec_nanos() as u64)
        .unwrap_or(0)
}

/// Run one provider turn — streaming assistant text to `on_chunk` as it generates (#1832) — and retry
/// *transient* failures with exponential backoff so a network blip or rate-limit doesn't abort the
/// agent run. Permanent errors (auth, bad request) return immediately; a transient failure is NOT
/// retried once text has streamed (re-streaming would double what the PTY already showed). `base_backoff`
/// is the first delay (doubled each retry); tests pass `Duration::ZERO`. (#1078 P4 / #1832)
async fn turn_streaming_with_retry<P: LlmProvider>(
    provider: &P,
    turn: &Turn,
    api_key: &str,
    base_backoff: Duration,
    retry_after: &dyn Fn() -> Option<Duration>,
    on_chunk: &mut dyn FnMut(&str),
) -> Result<TurnResult, String> {
    let mut attempt = 0;
    loop {
        // Whether THIS attempt streamed any text — gates retry (see the doc above).
        let emitted = std::cell::Cell::new(false);
        let result = {
            let mut guarded = |c: &str| {
                emitted.set(true);
                on_chunk(c);
            };
            provider.turn_streaming(turn, api_key, &mut guarded).await
        };
        match result {
            Ok(r) => return Ok(r),
            Err(e) if attempt < MAX_TURN_RETRIES && is_transient_error(&e) && !emitted.get() => {
                let hint = retry_after();
                let backoff = next_backoff(attempt as u32, base_backoff, hint, now_entropy());
                eprintln!(
                    "bsc-agent: transient provider error (attempt {}/{}), retrying in {}ms{}: {e}",
                    attempt + 1,
                    MAX_TURN_RETRIES,
                    backoff.as_millis(),
                    // Say WHOSE delay this is. A reader debugging a slow fleet needs to know whether
                    // the wait was the provider's instruction or our own guess.
                    if hint.is_some() { " (server-directed)" } else { "" },
                );
                tokio::time::sleep(backoff).await;
                attempt += 1;
            }
            Err(e) => return Err(e),
        }
    }
}

/// How many prior messages a resume replays in full.
///
/// BOUNDED, because a resumed conversation is exactly the case that can be huge: the measured worker
/// carried 39 messages including tool results, and a caged worker's results run to kilobytes. Dumping
/// all of it would bury the prompt the user is about to type at. The newest are the ones worth seeing,
/// so the tail is kept and the rest is COUNTED rather than dropped silently.
pub const REPLAY_TAIL: usize = 12;

/// Render a resumed conversation for the pane.
///
/// WHY THIS EXISTS. The resume itself already worked — the app passes `--continue`, the file loads,
/// and `run_agent` seeds the model with every message. But the session's init line clears the screen
/// and nothing was printed, so a correctly-resumed session was VISUALLY IDENTICAL to a fresh one. The
/// maintainer reported both the director and the worker "starting a fresh session each time" when in
/// fact the model had the whole history; the work was there and the evidence of it was not.
///
/// Reuses [`describe_tool_call`] and [`describe_tool_result`] rather than inventing a second style, so
/// a replayed turn reads exactly like the live one directly beneath it.
///
/// Pure: takes the messages, returns the text. The caller prints it.
pub fn replay_prior(prior: &[Msg]) -> String {
    if prior.is_empty() {
        return String::new();
    }
    let elided = prior.len().saturating_sub(REPLAY_TAIL);
    let mut out = format!(
        "\x1b[2m\u{25b8} resuming {} message(s) from the previous session\x1b[0m\n",
        prior.len()
    );
    if elided > 0 {
        // SAID, not dropped: a replay that quietly showed only the tail would misrepresent how much
        // context the model actually has.
        out.push_str(&format!(
            "\x1b[2m\u{2026}({elided} earlier message(s) not shown \u{b7} the model still has them)\x1b[0m\n"
        ));
    }
    for m in prior.iter().skip(elided) {
        match m {
            Msg::User(text) => out.push_str(&format!("\x1b[1m\u{203a} {}\x1b[0m\n", text.trim())),
            Msg::Assistant { text, tool_calls } => {
                let t = text.trim();
                if !t.is_empty() {
                    out.push_str(&format!("{t}\n"));
                }
                for tc in tool_calls {
                    out.push_str(&format!("[tool] {}\n", describe_tool_call(&tc.name, &tc.args)));
                }
            }
            // The RESULT is rendered by the same helper the live line uses, so its preview cap and
            // its "+N more lines" tail apply here too — which is what keeps a long replay bounded.
            Msg::ToolResult { content, .. } => {
                out.push_str(&format!("{}\n", describe_tool_result(ToolOutcome::Ok, content)));
            }
        }
    }
    out
}

/// Persist the conversation as JSON (best-effort) so a later `--continue` can resume it.
fn save_conversation(path: &Path, messages: &[Msg]) {
    if let Some(dir) = path.parent() {
        let _ = std::fs::create_dir_all(dir);
    }
    if let Ok(json) = serde_json::to_string(messages) {
        let _ = std::fs::write(path, json);
    }
}

/// Load a persisted conversation. Absent ⇒ empty; UNREADABLE ⇒ empty AND said out loud.
///
/// The distinction is the point. This swallowed every failure into an empty vec, so a conversation
/// that existed but could not be parsed was indistinguishable from one that never existed — and the
/// session silently started over. A resume whose failure mode is a silent fresh start is one where a
/// real loss can never be noticed.
///
/// A missing file stays quiet: that is the ordinary first-run case, not a fault.
pub fn load_conversation(path: &Path) -> Vec<Msg> {
    let raw = match std::fs::read_to_string(path) {
        Ok(r) => r,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Vec::new(),
        Err(e) => {
            eprintln!(
                "\x1b[33mbsc-agent: could not READ the prior conversation at {} ({e}) — starting fresh. \
                 Anything it held is still on disk.\x1b[0m",
                path.display()
            );
            return Vec::new();
        }
    };
    match serde_json::from_str(&raw) {
        Ok(v) => v,
        Err(e) => {
            eprintln!(
                "\x1b[33mbsc-agent: the prior conversation at {} did not parse ({e}) — starting fresh. \
                 The file is untouched; nothing was overwritten yet.\x1b[0m",
                path.display()
            );
            Vec::new()
        }
    }
}

#[cfg(test)]
mod tests {
    // ── the step budget ends with a HANDOFF, not a wall ──────────────────────────────────────────
    // (`the-step-budget-ends-with-a-handoff-not-a-wall`) The protocol used to ask the agent to run
    // `bsc-checkpoint` before running out. That asks the model least able to hold a long horizon to
    // notice, at exactly the right moment, that it is losing it — and a skipped checkpoint looks
    // exactly like one that was not needed, so the failure was unobservable. These pin the parts
    // that must hold with NO model cooperation at all.

    /// Serializes the env-var tests below. `cargo test` threads tests inside one binary, so two
    /// tests setting `BSC_CHECKPOINT_DOC` at once would see each other's value. (`cargo nextest`,
    /// what the gate runs, gives each test its own process and would not need this — but the suite
    /// has to be correct under both runners.)
    static ENV_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    fn asst(text: &str, calls: &[(&str, serde_json::Value)]) -> Msg {
        Msg::Assistant {
            text: text.to_string(),
            tool_calls: calls
                .iter()
                .map(|(n, a)| ToolCall { id: format!("id-{n}"), name: n.to_string(), args: a.clone() })
                .collect(),
        }
    }

    #[test]
    fn a_checkpoint_can_never_overflow_the_init_line() {
        // THE REGRESSION. The checkpoint is inlined into a shell command written to a PTY in
        // canonical mode, which Linux truncates past 4096 bytes — leaving an unterminated `$'…'`,
        // a shell parked at `>`, and no agent. Measured: a 1511-byte kickoff plus a 2221-byte
        // checkpoint plus the shell prefix and ANSI-C escaping went over, and the session would not
        // start. One line per tool call is unbounded growth, so the bound has to be enforced.
        // The size comes from the LAST assistant text (tool lines are already capped at 12), so the
        // realistic worst case is a long final message — which is exactly what a handoff is.
        let many: Vec<Msg> = (0..400)
            .map(|n| Msg::Assistant {
                text: "x".repeat(1500),
                tool_calls: vec![ToolCall {
                    id: "i".into(),
                    name: "bash".into(),
                    args: serde_json::json!({ "command": format!("command-number-{n}") }),
                }],
            })
            .collect();
        let bounded = bound_for_inline(&mechanical_checkpoint(&many, 60, 60));
        assert!(
            bounded.chars().count() <= CHECKPOINT_INLINE_BUDGET + 80,
            "a checkpoint must stay inlinable, got {} chars",
            bounded.chars().count(),
        );
        assert!(bounded.contains("BSC_CHECKPOINT_DOC"), "and say where the rest is: {bounded}");
    }

    #[test]
    fn a_short_checkpoint_is_left_exactly_as_it_was() {
        // The bound must not disturb the normal case, which is most of them.
        let short = mechanical_checkpoint(&[Msg::User("go".into())], 3, 60);
        assert_eq!(bound_for_inline(&short), short);
        assert!(!short.contains("truncated"));
    }

    #[test]
    fn bounding_cuts_on_a_char_boundary() {
        // The text is full of em-dashes and arrows; a byte slice would panic mid-character.
        let wide = "— ▸ ".repeat(2000);
        let out = bound_for_inline(&wide);
        assert!(out.chars().count() <= CHECKPOINT_INLINE_BUDGET + 80);
    }

