        const { assert!(HANDOFF_RESERVE >= 2, "the reserve must leave room to answer") };
        assert!(!HANDOFF_PROMPT.trim().is_empty(), "the prompt says what it wants");
        assert!(HANDOFF_PROMPT.contains("Do not start anything new"), "and what it forbids");
