    /// The CALL SITE's sum, not just `compact_messages`' argument — the bug lived in this addition.
    #[test]
    fn a_turns_fixed_cost_includes_the_tools_it_will_carry() {
        let defs: Vec<ToolDef> = (0..32)
            .map(|n| {
                let mut d = read_file_tool().def.clone();
                d.name = format!("{}_{n}", d.name);
                d
            })
            .collect();
        let sys = "s".repeat(4_000);
        let bare = estimate_tokens(&sys);

        let ordinary = fixed_turn_tokens(&sys, &defs, "", false);
        assert!(
            ordinary > bare,
            "an ordinary turn is charged for its tool schemas: {ordinary} vs {bare}"
        );
        assert_eq!(ordinary, bare + llm::estimate_tool_tokens(&defs));

        // The handoff turn is offered NO tools, so charging it for them would be wrong.
        assert_eq!(fixed_turn_tokens(&sys, &defs, "", true), bare, "the handoff turn carries none");
        // And no tools at all costs nothing either way.
        assert_eq!(fixed_turn_tokens(&sys, &[], "", false), bare);
    }

    /// The tool schemas ride in the same window and were counted as ZERO, so compaction aimed past it.
    ///
    /// MEASURED on the twitter-clone-test fleet: the 32 tool schemas are ~4,580 tokens against a
    /// 65,536-token window, and every dying session's request pinned to 65,506-65,524 — the signature
    /// of ollama truncating AT the window rather than a coincidence.
    #[test]
    fn the_budget_counts_the_tool_schemas_that_ride_in_the_same_window() {
        let defs: Vec<ToolDef> = (0..32)
            .map(|n| {
                let mut d = read_file_tool().def.clone();
                d.name = format!("{}_{n}", d.name);
                d
            })
            .collect();
        let tool_tokens = llm::estimate_tool_tokens(&defs);
        assert!(tool_tokens > 500, "32 serialized schemas are not free: {tool_tokens}");

        // A conversation that FITS while the schemas are ignored and does NOT once they are counted.
        let sys = "s".repeat(400);
        let sys_tokens = estimate_tokens(&sys);
        let msgs: Vec<Msg> = (0..12).map(|i| Msg::User(format!("{i}{}", "x".repeat(300)))).collect();
        let body: usize = msgs.iter().map(msg_tokens).sum();
        let budget = sys_tokens + body + tool_tokens / 2;

        let (ignored, did) = compact_messages(sys_tokens, msgs.clone(), budget, 0);
        assert!(!did, "with the schemas uncounted this conversation looks like it fits");
        assert_eq!(ignored.len(), msgs.len());

        let (counted, did) = compact_messages(sys_tokens + tool_tokens, msgs.clone(), budget, 0);
        assert!(did, "counting the schemas, the SAME conversation must be compacted");
        assert!(counted.len() < msgs.len(), "it actually dropped something: {}", counted.len());
    }

    /// ONE estimator behind the budget, not two. `agent.rs` kept `/4` after `crates/llm` measured 3.8.
    #[test]
    fn the_agent_and_the_llm_crate_agree_on_what_a_token_costs() {
        let long = "hello world ".repeat(500);
        for s in ["", "x", long.as_str(), "λ→∎ unicode"] {
            assert_eq!(
                estimate_tokens(s),
                llm::estimate_tokens(s),
                "two estimators across one budget calculation is how it under-counted"
            );
        }
        // And it must err HIGH of the old `/4`, which is the direction that decides an overflow.
        let big = "x".repeat(10_000);
        assert!(
            estimate_tokens(&big) > big.len() / 4,
            "`/4` under-counts by ~4%, and under-counting is what overflows the window"
        );
    }

    /// Build one assistant call + its result, the single-call shape a step actually produces.
    fn call_pair(id: &str, cmd: &str, result: &str) -> Vec<Msg> {
        vec![
            Msg::Assistant {
                text: String::new(),
                tool_calls: vec![ToolCall {
                    id: id.into(),
                    name: "bash".into(),
                    args: serde_json::json!({ "command": cmd }),
                }],
            },
            Msg::ToolResult { id: id.into(), content: result.into() },
        ]
    }

    /// The real captured shape: the director ran this same `find` four times, 20:30:46 through :57.
    #[test]
    fn four_identical_calls_collapse_to_one_copy_carrying_the_count() {
        let cmd = "cd /home/princess-bubblegum/.base-studio-code/worktrees/twitter-clone-test/twitter-clone-test--api && find . -type f -name \"*.ts\" | grep -v node_modules";
        let out = "./src/models/User.ts\n./src/routes/Auth.ts";
        let mut msgs = vec![Msg::User("go".into())];
        for n in 0..4 {
            msgs.extend(call_pair(&format!("c{n}"), cmd, out));
        }
        let before = msgs.len();
        let (folded, n) = fold_repeated_calls(msgs);
        assert_eq!(n, 3, "three of the four repeats are dropped");
        assert_eq!(folded.len(), before - 6, "an assistant AND its result go together, both times");

        let results: Vec<&String> = folded
            .iter()
            .filter_map(|m| match m {
                Msg::ToolResult { content, .. } => Some(content),
                _ => None,
            })
            .collect();
        assert_eq!(results.len(), 1, "exactly one copy of the result survives");
        assert!(results[0].starts_with(out), "the surviving body is the real output, unaltered");
        assert!(results[0].contains("ran 4 times"), "and it states the count: {}", results[0]);

        // PAIRING STAYS VALID: every result has an assistant call with its id immediately before it.
        for (i, m) in folded.iter().enumerate() {
            if let Msg::ToolResult { id, .. } = m {
                let ok = matches!(folded.get(i - 1), Some(Msg::Assistant { tool_calls, .. })
                    if tool_calls.iter().any(|t| &t.id == id));
                assert!(ok, "result at {i} lost its call");
            }
        }
    }

