    /// The safety rule: never drop a message carrying text or more than one call.
    #[test]
    fn a_message_with_text_or_several_calls_is_left_alone() {
        let two = vec![
            Msg::Assistant {
                text: String::new(),
                tool_calls: vec![
                    ToolCall { id: "x".into(), name: "bash".into(), args: serde_json::json!({"command":"ls"}) },
                    ToolCall { id: "y".into(), name: "bash".into(), args: serde_json::json!({"command":"ls"}) },
                ],
            },
            Msg::ToolResult { id: "x".into(), content: "same".into() },
            Msg::ToolResult { id: "y".into(), content: "same".into() },
        ];
        let (out, n) = fold_repeated_calls(two.clone());
        assert_eq!(n, 0, "multiple calls would leave a sibling's result dangling");
        assert_eq!(out.len(), two.len());

        let mut spoke = vec![Msg::Assistant {
            text: "I will check the routes".into(),
            tool_calls: vec![ToolCall { id: "a".into(), name: "bash".into(), args: serde_json::json!({"command":"ls"}) }],
        }, Msg::ToolResult { id: "a".into(), content: "same".into() }];
        spoke.extend(spoke.clone());
        let (out, n) = fold_repeated_calls(spoke.clone());
        assert_eq!(n, 0, "folding a message with text would discard what the model said");
        assert_eq!(out.len(), spoke.len());
    }

    /// The CALL SITE, not just the helper: what `run_agent` actually sends the model on a resume.
    ///
    /// The bug was one unconditional `messages.push`, so a test that only exercises `resume_turn`
    /// would stay green with the defect fully restored.
    #[tokio::test]
    async fn a_resumed_run_does_not_restate_the_task_to_the_model() {
        struct SeesMessages(std::sync::Arc<std::sync::Mutex<Vec<Vec<String>>>>);
        impl LlmProvider for SeesMessages {
            async fn complete(&self, _r: &LlmRequest, _k: &str) -> Result<serde_json::Value, String> {
                unreachable!()
            }
            async fn turn(&self, t: &Turn, _k: &str) -> Result<TurnResult, String> {
                self.0.lock().unwrap().push(
                    t.messages
                        .iter()
                        .filter_map(|m| match m {
                            Msg::User(u) => Some(u.clone()),
                            _ => None,
                        })
                        .collect(),
                );
                Ok(TurnResult {
                    text: "ok".into(),
                    tool_calls: vec![],
                    usage: serde_json::Value::Null,
                    stop_reason: "end_turn".into(),
                })
            }
        }
        let task = "Build the REST API: auth, posts, likes, feed";
        let prior = vec![
            Msg::User(task.into()),
            Msg::Assistant { text: "wrote the models".into(), tool_calls: vec![] },
        ];
        let seen = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let _ = run_agent(
            &SeesMessages(seen.clone()),
            "",
            "m",
            "",
            task,
            &[],
            &Permissions::default(),
            &Telemetry::disabled(),
            &prior,
            None,
            4,
            false,
        )
        .await;
        let sent = seen.lock().unwrap().clone();
        let users = sent.first().expect("the model was asked at least once");
        assert_eq!(
            users.iter().filter(|u| u.as_str() == task).count(),
            1,
            "the kickoff must appear ONCE, not be restated by the relaunch: {users:?}"
        );
        assert!(
            users.iter().any(|u| u.contains("RESUMING")),
            "and the new turn says it is a continuation: {users:?}"
        );
    }

    /// The REAL captured shape: the director emitted byte-identical reasoning and the SAME command on
    /// three consecutive steps, each returning 0 B, with both the fold and the notice firing.
    #[test]
    fn the_third_consecutive_identical_call_is_refused_rather_than_run() {
        let cmd = serde_json::json!({"command":
            "cd /home/princess-bubblegum/.base-studio-code/worktrees/twitter-clone-test/twitter-clone-test--api \
             && find . -name '*.ts' | grep -v README | grep -v Model | head -30"});
        let mut msgs = vec![Msg::User("coordinate the fleet".into())];
        assert_eq!(consecutive_identical_calls(&msgs, "bash", &cmd), 0, "nothing has run yet");

        for n in 0..2 {
            msgs.push(Msg::Assistant {
                text: "I need to find the main entry point".into(),
                tool_calls: vec![ToolCall { id: format!("c{n}"), name: "bash".into(), args: cmd.clone() }],
            });
            msgs.push(Msg::ToolResult { id: format!("c{n}"), content: String::new() });
        }
        let n = consecutive_identical_calls(&msgs, "bash", &cmd);
        assert_eq!(n, 2, "two identical runs, both empty");
        assert!(n >= REPEAT_REFUSAL_AFTER, "the third must be refused");

        let refusal = repeat_refusal("bash", &cmd, n, "");
        assert!(refusal.starts_with("error: refused"), "it lands as an ERROR the model must handle: {refusal}");
        assert!(refusal.contains("NO OUTPUT every time"), "it names what it kept getting: {refusal}");
        assert!(refusal.contains("Do something DIFFERENT"), "and what to do instead: {refusal}");
        // THE POINT: the refusal is not the empty string, so the context MOVES and the fold — which
        // only collapses byte-identical results — can no longer collapse it back into a fixed point.
        assert_ne!(refusal, "", "a refusal that matched the prior result would rebuild the fixed point");
        assert_ne!(result_body(&refusal), "");
    }

    /// CONSECUTIVE only. An intervening different call may have changed the world.
    #[test]
    fn a_different_call_in_between_resets_the_count() {
        let a = serde_json::json!({"command": "git status"});
        let b = serde_json::json!({"command": "npm test"});
        let mut msgs = vec![Msg::User("go".into())];
        let push = |m: &mut Vec<Msg>, id: &str, args: &serde_json::Value, out: &str| {
            m.push(Msg::Assistant {
                text: String::new(),
                tool_calls: vec![ToolCall { id: id.into(), name: "bash".into(), args: args.clone() }],
            });
            m.push(Msg::ToolResult { id: id.into(), content: out.into() });
        };
        push(&mut msgs, "1", &a, "clean");
        push(&mut msgs, "2", &a, "clean");
        assert_eq!(consecutive_identical_calls(&msgs, "bash", &a), 2, "two in a row");
        push(&mut msgs, "3", &b, "tests pass");
        assert_eq!(
            consecutive_identical_calls(&msgs, "bash", &a), 0,
            "a different call ran in between — the world may have moved, so `git status` is legitimate"
        );
    }

