    /// End to end through the real executor: the third call must not reach the tool at all.
    #[tokio::test]
    async fn a_looping_call_is_never_executed_a_third_time() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        static RUNS: AtomicUsize = AtomicUsize::new(0);
        RUNS.store(0, Ordering::SeqCst);
        let tool = Tool {
            def: ToolDef {
                name: "probe".into(),
                description: "counts its runs".into(),
                schema: serde_json::json!({"type": "object"}),
            },
            run: Box::new(|_args| {
                RUNS.fetch_add(1, Ordering::SeqCst);
                Ok(String::new()) // always empty — the captured 0 B shape
            }),
        };
        let args = serde_json::json!({});
        let tools = vec![tool];
        let mut messages = vec![Msg::User("go".into())];
        for n in 0..4 {
            let call = ToolCall { id: format!("c{n}"), name: "probe".into(), args: args.clone() };
            messages.push(Msg::Assistant { text: "same thought".into(), tool_calls: vec![call.clone()] });
            execute_tool_calls(
                &[call],
                &tools,
                &Permissions::default(),
                &Telemetry::disabled(),
                &mut messages,
                None,
            );
        }
        assert_eq!(
            RUNS.load(Ordering::SeqCst),
            REPEAT_REFUSAL_AFTER,
            "the tool must stop being RUN once it is looping, not merely be commented on"
        );
        let results: Vec<&String> = messages
            .iter()
            .filter_map(|m| match m {
                Msg::ToolResult { content, .. } => Some(content),
                _ => None,
            })
            .collect();
        assert_eq!(results.len(), 4, "every call still produced a result");
        assert!(results[2].starts_with("error: refused"), "the third is refused: {}", results[2]);
        assert!(results[3].starts_with("error: refused"), "and it stays refused: {}", results[3]);
    }

    /// The REAL captured shape: four launches, one kickoff, from the twitter-clone-test worker's own
    /// conversation.json — four identical "Build the REST API" user turns across 56 messages.
    #[test]
    fn a_relaunch_continues_instead_of_restating_the_task() {
        let task = "Build the REST API: auth, posts, likes, feed";

        // First launch: no prior, so the task is stated — once.
        assert!(matches!(resume_turn(&[], task), Msg::User(u) if u == task));

        // Every launch after it resumes a conversation that already contains the task.
        let mut convo = vec![Msg::User(task.into())];
        for launch in 2..=4 {
            let turn = resume_turn(&convo, task);
            let Msg::User(u) = &turn else { panic!("a user turn") };
            assert_ne!(u, task, "launch {launch} restated the kickoff — that IS the loop");
            assert!(u.contains("RESUMING"), "it says what this launch is: {u}");
            assert!(u.contains("Do not start over"), "and what not to do: {u}");
            convo.push(turn);
            // whatever work that launch did
            convo.push(Msg::Assistant { text: format!("did work {launch}"), tool_calls: vec![] });
        }
        let stated: usize = convo
            .iter()
            .filter(|m| matches!(m, Msg::User(u) if u == task))
            .count();
        assert_eq!(stated, 1, "the kickoff appears exactly ONCE across four launches");
    }

