    #[test]
    fn the_block_is_last_so_the_freshest_facts_are_nearest() {
        // Recency is the only positional advantage available in a prompt of 13-54k tokens, and these
        // are the facts most likely to have changed since the last turn. The block also CLAIMS
        // precedence over older context, so the layout has to support the claim.
        // Built with the REAL renderer, so the claim it makes is the one being positioned.
        let env = render_env_block(&EnvFacts { cwd: Some("/x".into()), ..Default::default() });
        let sys = compose_turn_system("PROJECT DOC", Some("ISSUES"));
        assert!(
            !sys.contains("# Environment"),
            "the volatile block must NOT be in the stable prefix — that cost 41s a step: {sys}"
        );
        assert!(sys.find("PROJECT DOC").unwrap() < sys.find("ISSUES").unwrap(), "documents, then issues");
        // It still claims precedence over older context, and the tail is where that claim holds best.
        assert!(env.contains("Trust them over anything older"));
        let tail = env_message(&env, false).expect("ordinary turns carry it");
        assert!(matches!(&tail, Msg::User(u) if u.contains("# Environment")));
    }

    /// THE POINT OF THE MOVE, asserted rather than inferred.
    ///
    /// llama-server reuses the longest common PREFIX of a request. Turn N+1 must therefore be
    /// byte-identical to turn N for everything up to the new content — otherwise the whole history
    /// re-prefills, which is the 41.15 s measured on task 61186 for a 58,648-token prompt.
    #[test]
    fn only_the_tail_changes_when_the_environment_changes() {
        let facts = |branch: &str| {
            render_env_block(&EnvFacts {
                cwd: Some("/repo".into()),
                git: Some((branch.into(), "dirty".into())),
                ..Default::default()
            })
        };
        let history = vec![
            Msg::User("build the API".into()),
            Msg::Assistant { text: "on it".into(), tool_calls: vec![] },
        ];

        // Two consecutive turns whose ONLY difference is the environment.
        let sys_a = compose_turn_system("PROJECT DOC", Some("ISSUES"));
        let sys_b = compose_turn_system("PROJECT DOC", Some("ISSUES"));
        assert_eq!(sys_a, sys_b, "the system prompt is the STABLE prefix and must not move");

        let mut a = history.clone();
        a.extend(env_message(&facts("main"), false));
        let mut b = history.clone();
        b.extend(env_message(&facts("feature/x"), false));

        // `Msg` carries no `PartialEq`, and the property under test is BYTE equality of what gets
        // serialized — so compare the rendered form, which is what the provider actually sends.
        let render = |m: &[Msg]| format!("{m:?}");
        assert_eq!(a.len(), b.len());
        assert_eq!(
            render(&a[..history.len()]),
            render(&b[..history.len()]),
            "every message before the tail is byte-identical — that IS the reusable prefix"
        );
        assert_ne!(
            render(&a[history.len()..]),
            render(&b[history.len()..]),
            "and the change lands in the tail, where it is cheap"
        );

        // The env is the FINAL message, so nothing stale sits after the freshest facts.
        assert!(matches!(a.last(), Some(Msg::User(u)) if u.contains("# Environment")));
    }

