    /// A provider that scripts two turns: (1) call `read_file` on a temp path, then
    /// (2) — once it sees the tool result echoed back — return the final text. Proves
    /// the loop executes a tool and feeds the result into the next turn. No network.
    struct MockProvider {
        step: Cell<usize>,
        file: String,
    }

    impl LlmProvider for MockProvider {
        async fn complete(&self, _req: &LlmRequest, _key: &str) -> Result<serde_json::Value, String> {
            unreachable!("agent loop uses turn(), not complete()")
        }

        async fn turn(&self, t: &Turn, _key: &str) -> Result<TurnResult, String> {
            let n = self.step.get() + 1;
            self.step.set(n);
            if n == 1 {
                Ok(TurnResult {
                    text: String::new(),
                    tool_calls: vec![ToolCall {
                        id: "c1".into(),
                        name: "read_file".into(),
                        args: serde_json::json!({ "path": self.file }),
                    }],
                    usage: serde_json::Value::Null,
                    stop_reason: "tool_use".into(),
                })
            } else {
                let saw_result = t.messages.iter().any(
                    |m| matches!(m, Msg::ToolResult { content, .. } if content.contains("HELLO")),
                );
                Ok(TurnResult {
                    text: if saw_result { "done: saw HELLO".into() } else { "missing tool result".into() },
                    tool_calls: vec![],
                    usage: serde_json::Value::Null,
                    stop_reason: "end_turn".into(),
                })
            }
        }
    }

    #[tokio::test]
    async fn loop_runs_tool_then_returns_final_text() {
        let path = std::env::temp_dir().join("bsc_agent_p2a_test.txt");
        std::fs::write(&path, "HELLO world").unwrap();
        let mock = MockProvider {
            step: Cell::new(0),
            file: path.to_string_lossy().into_owned(),
        };
        let tools = vec![read_file_tool()];
        let out = run_agent(&mock, "", "m", "", "read the file", &tools, &Permissions::default(), &Telemetry::disabled(), &[], None, 5, false)
            .await
            .unwrap();
        assert_eq!(out, "done: saw HELLO");
        assert_eq!(mock.step.get(), 2); // exactly two turns
        let _ = std::fs::remove_file(&path);
    }

    // ── the OUTCOME reaches the pane (#a-local-agent-turn-is-invisible-while-it-runs-and-lost-if-it-dies) ──

    #[test]
    fn a_failing_tool_call_is_unmissable_and_shown_in_full() {
        // THE REGRESSION. The twitter-clone-test director failed 7 of one turn's 18 calls with this
        // exact string and the pane showed seven ordinary-looking `[tool]` lines — nothing said 39%
        // of the turn was failing. An error is the case this feature exists for, so it is not
        // abbreviated into the same shape as a success.
        let line = describe_tool_result(ToolOutcome::Error, "error: unknown tool 'bsc-fleet'");
        assert!(line.contains("ERROR"), "{line}");
        assert!(line.contains("unknown tool 'bsc-fleet'"), "the cause is whole: {line}");
        assert!(!line.contains("ok"), "a failure must not read as a success: {line}");

        // A denial is its own outcome — the gate refused it before it ran, which is a different fact
        // from a tool that ran and failed.
        let denied = describe_tool_result(ToolOutcome::Denied, "write is denied outside your owned globs");
        assert!(denied.contains("DENIED") && denied.contains("owned globs"), "{denied}");
    }

    #[test]
    fn a_successful_result_shows_a_few_lines_and_its_size() {
        // A couple of lines, not one: `ok · 4.2 KB` proves the call returned but says nothing about
        // WHAT, and the reader still has to fetch it to know whether it was the answer they wanted.
        let out = "line one\nline two\nline three\nline four\nline five\n";
        let line = describe_tool_result(ToolOutcome::Ok, out);
        assert!(line.contains("ok"), "{line}");
        assert!(line.contains(&format!("{} B", out.len())), "the size is stated: {line}");
        for kept in ["line one", "line two", "line three"] {
            assert!(line.contains(kept), "{kept} should be previewed: {line}");
        }
        assert!(!line.contains("line four"), "beyond the preview budget: {line}");
        assert!(line.contains("+2 more lines"), "and it SAYS what it withheld: {line}");
    }

    #[test]
    fn output_is_bounded_so_one_result_cannot_take_the_pane() {
        // A store dump or a wide grep is megabytes on ONE line. Unbounded, a single result buries the
        // conversation it is supposed to be part of.
        let wide = "x".repeat(10_000);
        let line = describe_tool_result(ToolOutcome::Ok, &wide);
        assert!(line.chars().count() < RESULT_LINE_WIDTH + 200, "one wide line is cut: {}", line.len());
        assert!(line.contains('…'), "and the cut is marked");

        let tall = (0..5_000).map(|i| format!("row {i}")).collect::<Vec<_>>().join("\n");
        let line = describe_tool_result(ToolOutcome::Ok, &tall);
        assert!(line.lines().count() <= RESULT_PREVIEW_LINES + 2, "a tall result is cut: {line}");

        // Even an error is capped — a tool that fails by printing a megabyte must not take the pane
        // either, though its budget is far larger because the cause is the whole point.
        let huge_err = "e".repeat(ERROR_PREVIEW_BUDGET * 3);
        let line = describe_tool_result(ToolOutcome::Error, &huge_err);
        assert!(line.chars().count() < ERROR_PREVIEW_BUDGET + 200);
        assert!(line.contains("truncated"), "and it says so: {line}");
    }

