    #[test]
    fn a_tool_call_is_described_by_what_it_acts_on_not_just_its_name() {
        // `[tool] bash` was the whole trace. For a session whose surface IS bash, every step looked
        // identical — there was no way to tell progress from a loop.
        let d = |n: &str, a: serde_json::Value| describe_tool_call(n, &a);
        assert_eq!(d("bash", serde_json::json!({"command": "cargo test"})), "bash cargo test");
        assert_eq!(d("read_file", serde_json::json!({"path": "src/lib.rs"})), "read_file src/lib.rs");
        assert_eq!(d("grep", serde_json::json!({"pattern": "TODO"})), "grep TODO");
        // Nothing identifying ⇒ the bare name, never a dangling separator.
        assert_eq!(d("list", serde_json::json!({})), "list");
        assert_eq!(d("list", serde_json::json!({"command": "   "})), "list");
    }

