    /// The real captured shape. A fleet worktree path is longer than the old 80-character budget, so
    /// EVERY `cd <path> && <verb>` rendered as the same truncated prefix — six different commands,
    /// with results of 180, 384, 151, 461, 109 and 109 bytes, printed identically in the pane.
    #[test]
    fn two_commands_differing_only_at_the_end_do_not_render_identically() {
        let base = "cd /home/princess-bubblegum/.base-studio-code/worktrees/twitter-clone-test/twitter-clone-test--api";
        assert!(
            base.chars().count() > 80,
            "the captured path must exceed the old head budget or this test proves nothing: {}",
            base.chars().count()
        );
        let a = describe_tool_call("bash", &serde_json::json!({"command": format!("{base} && git status")}));
        let b = describe_tool_call("bash", &serde_json::json!({"command": format!("{base} && npm test")}));
        assert_ne!(a, b, "two DIFFERENT commands must never render the same:\n  {a}\n  {b}");
        assert!(a.ends_with("&& git status"), "the distinguishing tail must survive: {a}");
        assert!(b.ends_with("&& npm test"), "the distinguishing tail must survive: {b}");
