    #[test]
    fn eliding_drops_the_middle_and_degrades_to_the_tail() {
        assert_eq!(elide_middle("short", 96), "short", "under budget is untouched");
        let s: String = ('a'..='z').cycle().take(200).collect();
        let out = elide_middle(&s, 96);
        assert_eq!(out.chars().count(), 96, "the budget is a character count, not a byte count");
        assert!(out.contains('\u{2026}'), "the drop is marked: {out}");
        assert!(out.ends_with(&s[s.len() - 10..]), "the TAIL is the half kept: {out}");
        // A budget too small for both ends still keeps the end.
        let tiny = elide_middle(&s, 4);
        assert!(tiny.ends_with(&s[s.len() - 2..]), "a tiny budget degrades to the tail: {tiny}");
    }

    /// Build one turn's worth of history: a user message, then N assistant calls each with its result.
    fn turn_with(calls: &[(&str, serde_json::Value, &str)]) -> Vec<Msg> {
        let mut msgs = vec![Msg::User("go".into())];
        for (n, (name, args, result)) in calls.iter().enumerate() {
            let id = format!("c{n}");
            msgs.push(Msg::Assistant {
                text: String::new(),
                tool_calls: vec![ToolCall { id: id.clone(), name: (*name).into(), args: args.clone() }],
            });
            msgs.push(Msg::ToolResult { id, content: (*result).to_string() });
        }
        msgs
    }

    #[test]
    fn an_identical_call_with_an_identical_result_is_reported_to_the_model() {
        let cmd = serde_json::json!({"command": "cd /home/princess-bubblegum/.base-studio-code/worktrees/twitter-clone-test/twitter-clone-test--api && git status"});
        let msgs = turn_with(&[("bash", cmd.clone(), "nothing to commit")]);
        let notice = repeat_notice(&msgs, "bash", &cmd, "nothing to commit")
            .expect("a second identical call with the same bytes back must be reported");
        assert!(notice.contains("call #2"), "it says WHICH repeat this is: {notice}");
        assert!(notice.contains("git status"), "it names the call, tail included: {notice}");
        // BOUNDED: it must not quote the earlier output back — that output is already in the
        // conversation, and copying it grows the context by the bytes being complained about.
        assert!(!notice.contains("nothing to commit"), "the earlier result is not re-quoted: {notice}");
        assert!(notice.lines().count() <= 4, "one short paragraph, not a report: {notice}");

        // It escalates with the count rather than repeating one flat sentence.
        let msgs3 = turn_with(&[
            ("bash", cmd.clone(), "nothing to commit"),
            ("bash", cmd.clone(), "nothing to commit"),
        ]);
        let third = repeat_notice(&msgs3, "bash", &cmd, "nothing to commit").expect("still reported");
        assert!(third.contains("call #3"), "the count is real: {third}");
    }

    #[test]
    fn a_repeat_that_returned_something_different_is_not_remarked_on() {
        // THE FALSE POSITIVE THIS EXISTS TO AVOID: re-running a cheap read is legitimate when the
        // world moved under it — `git status` after a commit is the whole point of running it twice.
        let cmd = serde_json::json!({"command": "git status"});
        let msgs = turn_with(&[("bash", cmd.clone(), "1 file changed")]);
        assert!(
            repeat_notice(&msgs, "bash", &cmd, "nothing to commit").is_none(),
            "a repeat whose result CHANGED was productive and must stay silent"
        );
        // A different call entirely is likewise silent.
        let other = serde_json::json!({"command": "git log"});
        assert!(repeat_notice(&msgs, "bash", &other, "1 file changed").is_none());
        // And the very first call of all is never a repeat.
        assert!(repeat_notice(&[Msg::User("go".into())], "bash", &cmd, "x").is_none());
    }

    #[test]
    fn the_notice_is_scoped_to_the_current_turn() {
        // Re-checking state at the top of a NEW turn is ordinary work, not a loop — the step budget
        // that the loop wastes is per-turn, so the window that detects it is per-turn too.
        let cmd = serde_json::json!({"command": "git status"});
        let mut msgs = turn_with(&[("bash", cmd.clone(), "clean")]);
        assert!(repeat_notice(&msgs, "bash", &cmd, "clean").is_some(), "same turn: reported");
        msgs.push(Msg::User("now do the next thing".into()));
        assert!(
            repeat_notice(&msgs, "bash", &cmd, "clean").is_none(),
            "a new user turn resets the window"
        );
    }

