    #[tokio::test]
    async fn the_handoff_turn_is_offered_no_tools_at_all() {
        // The guarantee that makes the wording redundant: on the handoff turn the model is handed an
        // EMPTY tool list, so writing a file is impossible rather than discouraged.
        struct SeesTools(std::sync::Arc<std::sync::Mutex<Vec<usize>>>);
        impl LlmProvider for SeesTools {
            async fn complete(&self, _r: &LlmRequest, _k: &str) -> Result<serde_json::Value, String> {
                unreachable!()
            }
            async fn turn(&self, t: &Turn, _k: &str) -> Result<TurnResult, String> {
                self.0.lock().unwrap().push(t.tools.len());
                let asked = t.messages.iter().any(|m| matches!(m, Msg::User(u) if u == HANDOFF_PROMPT));
                if asked {
                    return Ok(TurnResult { text: "handed off".into(), tool_calls: vec![], usage: serde_json::Value::Null, stop_reason: "end_turn".into() });
                }
                Ok(TurnResult {
                    text: String::new(),
                    tool_calls: vec![ToolCall { id: "x".into(), name: "read_file".into(), args: serde_json::json!({"path":"/nope"}) }],
                    usage: serde_json::Value::Null,
                    stop_reason: "tool_use".into(),
                })
            }
        }
        let seen = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let tools = vec![read_file_tool()];
        let _ = run_agent(&SeesTools(seen.clone()), "", "m", "", "go", &tools, &Permissions::default(), &Telemetry::disabled(), &[], None, 6, false).await;
        let counts = seen.lock().unwrap().clone();
        assert!(counts.iter().any(|n| *n > 0), "ordinary turns still get their tools: {counts:?}");
        assert_eq!(*counts.last().unwrap(), 0, "the handoff turn must be offered none: {counts:?}");
    }

    // The env lock IS held across the await, deliberately. `BSC_CHECKPOINT_DOC` is process-global
    // and `run_agent` reads it DURING the await, so releasing the guard first would let a sibling
    // test overwrite it mid-run — the exact race the lock exists to stop. Clippy's concern is an
    // async runtime deadlocking on a blocking lock; there is no other task contending for this one
    // (and under `cargo nextest`, what the gate runs, each test is its own process anyway).
    #[allow(clippy::await_holding_lock)]
    #[tokio::test]
    async fn a_successful_handoff_still_leaves_a_checkpoint_on_disk() {
        // THE HOLE the first pass shipped. The handoff is injected, the model DOES answer it — and
        // `answered = true` then skips the whole `if !answered` block, which is the only place the
        // checkpoint doc is written. So the case where the mechanism WORKS was the case where the
        // successor got nothing: the handoff existed only inside a conversation nobody reads.
        //
        // No unit test could see it — the first pass tested `mechanical_checkpoint` and
        // `write_checkpoint_doc` in isolation, and both were correct. Only driving the loop shows it.
        struct HandsOff;
        impl LlmProvider for HandsOff {
            async fn complete(&self, _r: &LlmRequest, _k: &str) -> Result<serde_json::Value, String> {
                unreachable!()
            }
            async fn turn(&self, t: &Turn, _k: &str) -> Result<TurnResult, String> {
                // Answer the handoff when it arrives; otherwise keep asking for tools.
                // Match the CONSTANT, never a word inside it: the wording changed once already
                // (it used to say "write a handoff", which is what made a model write a file) and a
                // substring match turned that into two silently-failing tests.
                let asked = t.messages.iter().any(|m| matches!(m, Msg::User(u) if u == HANDOFF_PROMPT));
                if asked {
                    return Ok(TurnResult {
                        text: "Handed off: parser done, printer next, start at print.rs:40.".into(),
                        tool_calls: vec![],
                        usage: serde_json::Value::Null,
                        stop_reason: "end_turn".into(),
                    });
                }
                Ok(TurnResult {
                    text: String::new(),
                    tool_calls: vec![ToolCall { id: "x".into(), name: "read_file".into(), args: serde_json::json!({"path":"/nope"}) }],
                    usage: serde_json::Value::Null,
                    stop_reason: "tool_use".into(),
                })
            }
        }
        let _lock = ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let dir = std::env::temp_dir().join(format!("bsc-handoff-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let doc = dir.join("checkpoint.md");
        std::env::set_var("BSC_CHECKPOINT_DOC", &doc);

        let tools = vec![read_file_tool()];
        let out = run_agent(&HandsOff, "", "m", "", "go", &tools, &Permissions::default(), &Telemetry::disabled(), &[], None, 6, false).await;

        std::env::remove_var("BSC_CHECKPOINT_DOC");
        assert!(out.is_ok(), "the model answered the handoff, so the turn did not error: {out:?}");
        let written = std::fs::read_to_string(&doc)
            .expect("a checkpoint must be on disk after a handoff — it is the only thing the next launch reads");
        assert!(written.contains("print.rs:40"), "the agent's handoff must reach the doc: {written}");
        let _ = std::fs::remove_dir_all(&dir);
    }

