    /// A turn that is still RUNNING has already been persisted — the durability half of
    /// #a-local-agent-turn-is-invisible-while-it-runs-and-lost-if-it-dies.
    ///
    /// `save_conversation` used to run only when a turn ENDED, so a twenty-step director turn wrote
    /// nothing for minutes and a kill mid-turn lost all of it. MEASURED after two app relaunches: the
    /// twitter-clone-test conversation held exactly one turn and everything before it was gone.
    ///
    /// This drives a provider that makes a tool call and then never finishes, so the only way the
    /// file can exist at the end is a MID-TURN save.
    #[tokio::test]
    async fn a_turn_is_persisted_step_by_step_not_only_when_it_ends() {
        struct NeverFinishes;
        impl LlmProvider for NeverFinishes {
            async fn complete(&self, _r: &LlmRequest, _k: &str) -> Result<serde_json::Value, String> {
                unreachable!()
            }
            async fn turn(&self, _t: &Turn, _k: &str) -> Result<TurnResult, String> {
                // Every step asks for the same tool and never produces a final answer.
                Ok(TurnResult {
                    text: String::new(),
                    tool_calls: vec![ToolCall {
                        id: "c1".into(),
                        name: "noop".into(),
                        args: serde_json::json!({}),
                    }],
                    usage: serde_json::json!({}),
                    stop_reason: "tool_use".into(),
                })
            }
        }
        let dir = std::env::temp_dir().join(format!("bsc_midturn_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let session = dir.join("conversation.json");
        let tools = vec![Tool {
            def: ToolDef { name: "noop".into(), description: String::new(), schema: serde_json::json!({}) },
            run: Box::new(|_| Ok("done".into())),
        }];

        // Budget of 2 steps: it exhausts them without ever answering.
        let _ = run_agent(&NeverFinishes, "", "m", "", "go", &tools, &Permissions::default(),
                          &Telemetry::disabled(), &[], Some(&session), 2, false).await;

        let saved = load_conversation(&session);
        assert!(!saved.is_empty(), "the turn's work was persisted while it ran");

        // WELL-FORMED AT EVERY WRITE is the property that makes a resume safe: each assistant message
        // carrying N tool_calls must be followed by N tool results, or `--continue` would replay a
        // shape the providers reject. This is why the save is once per STEP and not once per call.
        let mut expected = 0usize;
        let mut results = 0usize;
        for m in &saved {
            match m {
                Msg::Assistant { tool_calls, .. } => {
                    assert_eq!(results, expected, "a step's results must all be present before the next");
                    expected += tool_calls.len();
                }
                Msg::ToolResult { .. } => results += 1,
                _ => {}
            }
        }
        assert_eq!(results, expected, "every tool call the file records has its result");
        assert!(expected > 0, "the run really did make tool calls");

        let _ = std::fs::remove_dir_all(&dir);
    }

