    /// BOUNDED. A resumed conversation is exactly the case that can be huge — the measured worker
    /// carried 39 messages with kilobyte tool results — and burying the prompt would trade one
    /// invisible state for another.
    #[test]
    fn a_long_replay_keeps_the_tail_and_counts_the_rest() {
        let prior: Vec<Msg> = (0..40).map(|i| Msg::User(format!("msg{i}"))).collect();
        let out = replay_prior(&prior);
        assert!(out.contains("resuming 40 message(s)"), "{out}");
        // The ELIDED count is stated: showing only the tail without saying so would misrepresent how
        // much context the model actually has.
        assert!(out.contains("(28 earlier message(s) not shown"), "{out}");
        assert!(out.contains("the model still has them"), "{out}");
        assert!(out.contains("msg39"), "the newest is kept");
        assert!(!out.contains("msg11"), "the oldest is not: {out}");
        assert!(out.contains("msg28"), "exactly the last REPLAY_TAIL are kept");
    }

    /// `load_conversation` is forgiving: a missing or malformed file yields an empty prior
    /// (a fresh conversation), never a panic. (#1144)
    #[test]
    fn load_conversation_empty_on_missing_or_garbage() {
        let dir = std::env::temp_dir().join(format!("bsc_p3_resume_load_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let missing = dir.join("nope.json");
        assert!(load_conversation(&missing).is_empty());
        let garbage = dir.join("garbage.json");
        std::fs::write(&garbage, "not json {{").unwrap();
        assert!(load_conversation(&garbage).is_empty());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn is_transient_error_classifies_retryable_vs_permanent() {
        // Transient: transport, rate-limit, 5xx (every provider formats these identically).
        assert!(is_transient_error("Request failed: error sending request"));
        assert!(is_transient_error("API error (429 Too Many Requests): slow down"));
        assert!(is_transient_error("API error (503 Service Unavailable): try again"));
        assert!(is_transient_error("API error (529): Overloaded"));
        // Permanent: auth / bad request / not found — no point retrying.
        assert!(!is_transient_error("API error (401 Unauthorized): bad key"));
        assert!(!is_transient_error("API error (400 Bad Request): context too long"));
        assert!(!is_transient_error("Failed to parse response: eof"));
    }

    /// Serialises the tests that touch `LAST_RETRY_AFTER`, which is process-global.
    ///
    /// Under `cargo nextest` each test gets its own PROCESS and cannot collide; under `cargo test`
    /// they are parallel threads in one process and do. The gate runs nextest, so without this a race
    /// here would be invisible to the gate and reproducible only locally — the failure shape this
    /// repo keeps being caught by. Poisoning is recovered, so a panicking sibling cannot cascade.
    static RETRY_HINT_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    /// THE SERVER'S INSTRUCTION WINS over the local schedule. Guessing a shorter delay than the
    /// provider asked for is how a fleet turns one rate limit into several.
    #[test]
    fn a_retry_after_beats_the_local_schedule() {
        let base = Duration::from_millis(500);
        // Attempt 0's local delay would be 500ms; the server said 10s.
        let d = next_backoff(0, base, Some(Duration::from_secs(10)), 0);
        assert!(d >= Duration::from_secs(5), "the server's 10s is honoured, not the local 500ms: {d:?}");

        // And it wins even when the local schedule has grown past it.
        let d = next_backoff(2, Duration::from_secs(30), Some(Duration::from_secs(1)), 0);
        assert!(d < Duration::from_secs(30), "a SHORTER instruction also wins: {d:?}");
    }

    /// An absurd instruction must not park a worker. A provider may legitimately say "an hour".
    #[test]
    fn an_absurd_retry_after_is_capped() {
        let d = next_backoff(0, Duration::from_millis(500), Some(Duration::from_secs(3600)), u64::MAX);
        assert!(d <= RETRY_AFTER_CAP, "capped at {RETRY_AFTER_CAP:?}, got {d:?}");
        assert!(d >= RETRY_AFTER_CAP / 2, "but still a real wait: {d:?}");
    }

    /// A provider that says nothing still backs off, and still doubles.
    #[test]
    fn the_local_schedule_is_the_fallback_and_still_grows() {
        let base = Duration::from_secs(4);
        // With entropy 0 the jitter contributes nothing, so these are the floors: base/2 per attempt.
        let a0 = next_backoff(0, base, None, 0);
        let a1 = next_backoff(1, base, None, 0);
        let a2 = next_backoff(2, base, None, 0);
        assert_eq!(a0, Duration::from_secs(2));
        assert_eq!(a1, Duration::from_secs(4));
        assert_eq!(a2, Duration::from_secs(8), "still doubling: base, 2x, 4x");
    }

    /// THE PROPERTY THE ITEM EXISTS FOR. Two clients backing off from the SAME instant with the SAME
    /// schedule must not retry together — otherwise the second burst is as sharp as the first.
    #[test]
    fn two_clients_do_not_retry_in_lockstep() {
        let base = Duration::from_secs(8);
        // Same attempt, same base, same (absent) hint — only the entropy differs, as it would across
        // two processes whose clocks are not synchronised to the nanosecond.
        let a = next_backoff(0, base, None, 1_000);
        let b = next_backoff(0, base, None, 999_999_999);
        assert_ne!(a, b, "identical inputs but different entropy must not land together");

        // And the spread is bounded: every draw sits in [base/2, base], so jitter decorrelates
        // WITHOUT letting a client retry immediately after being told to slow down.
        for e in [0u64, 1, 12_345, u64::MAX / 3, u64::MAX] {
            let d = next_backoff(0, base, None, e);
            assert!(d >= base / 2, "never shorter than half: {d:?}");
            assert!(d <= base, "never longer than the schedule: {d:?}");
        }

        // A spread of ONE value is not a spread — prove the draws actually differ across many.
        let seen: std::collections::BTreeSet<u128> =
            (0..64u64).map(|i| next_backoff(0, base, None, i * 7_919_777).as_nanos()).collect();
        assert!(seen.len() > 8, "expected a real spread, got {} distinct delays", seen.len());
    }

    /// A zero base is what the loop's own tests pass; it must stay zero rather than panicking on a
    /// modulo by zero.
    #[test]
    fn a_zero_base_stays_zero() {
        assert_eq!(next_backoff(0, Duration::ZERO, None, u64::MAX), Duration::ZERO);
        assert_eq!(jittered(Duration::ZERO, 12345), Duration::ZERO);
    }

    /// 529 Overloaded is Anthropic's own, and it must be honoured exactly like a 429 — both are the
    /// server saying "not now".
    #[test]
    fn a_529_carries_its_instruction_exactly_like_a_429() {
        let _g = RETRY_HINT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let cap = RetryAfterCapture { inner: None };
        let limits = llm::ratelimit::parse_rate_limits(vec![("retry-after", "7")]);

        for status in [429u16, 529, 503] {
            *LAST_RETRY_AFTER.lock().unwrap() = None;
            llm::ratelimit::RateLimitObserver::observe(&cap, "https://api/x", status, &limits);
            assert_eq!(
                last_retry_after(),
                Some(Duration::from_secs(7)),
                "status {status} must carry its Retry-After"
            );
        }

        // A SUCCESS carrying the header is not an instruction to wait before the next turn.
        *LAST_RETRY_AFTER.lock().unwrap() = None;
        llm::ratelimit::RateLimitObserver::observe(&cap, "https://api/x", 200, &limits);
        assert_eq!(last_retry_after(), None, "a 200 is not telling us to slow down");
    }

    /// The hint is CONSUMED, so a stale instruction cannot delay a later failure the server did not
    /// ask us to wait for.
    #[test]
    fn the_hint_is_consumed_not_remembered() {
        let _g = RETRY_HINT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let cap = RetryAfterCapture { inner: None };
        let limits = llm::ratelimit::parse_rate_limits(vec![("retry-after", "5")]);
        *LAST_RETRY_AFTER.lock().unwrap() = None;
        llm::ratelimit::RateLimitObserver::observe(&cap, "https://api/x", 429, &limits);
        assert_eq!(last_retry_after(), Some(Duration::from_secs(5)));
        assert_eq!(last_retry_after(), None, "read once — a stale hint must not delay the next failure");
    }

    /// Installing the capture must not silently disable the headroom recorder that already holds the
    /// one observer slot.
    #[test]
    fn the_capture_forwards_to_the_observer_it_displaces() {
        let _g = RETRY_HINT_LOCK.lock().unwrap_or_else(|e| e.into_inner());

        #[derive(Default)]
        struct Inner(std::sync::Mutex<usize>);
        impl llm::ratelimit::RateLimitObserver for Inner {
            fn observe(&self, _u: &str, _s: u16, _l: &llm::ratelimit::RateLimits) {
                *self.0.lock().unwrap() += 1;
            }
        }
        let inner = std::sync::Arc::new(Inner::default());
        let cap = RetryAfterCapture { inner: Some(inner.clone()) };

        let limits = llm::ratelimit::parse_rate_limits(vec![("retry-after", "3")]);
        llm::ratelimit::RateLimitObserver::observe(&cap, "https://api/x", 429, &limits);
        assert_eq!(*inner.0.lock().unwrap(), 1, "the displaced observer still ran");
        assert_eq!(last_retry_after(), Some(Duration::from_secs(3)), "and the hint was captured");
    }

    /// A provider whose `turn` fails (with `err`) for the first `fail_times` calls, then
    /// succeeds — so the retry policy can be exercised without real network/timing.
    struct FlakyProvider {
        calls: AtomicUsize,
        fail_times: usize,
        err: String,
    }
    impl LlmProvider for FlakyProvider {
        async fn complete(&self, _r: &LlmRequest, _k: &str) -> Result<serde_json::Value, String> {
            unreachable!()
        }
        async fn turn(&self, _t: &Turn, _k: &str) -> Result<TurnResult, String> {
            let n = self.calls.fetch_add(1, Ordering::SeqCst);
            if n < self.fail_times {
                Err(self.err.clone())
            } else {
                Ok(TurnResult { text: "ok".into(), ..Default::default() })
            }
        }
    }
    fn empty_turn() -> Turn {
        Turn { system: String::new(), messages: vec![], tools: vec![], model: "m".into(), max_tokens: 16 }
    }

    #[tokio::test]
    async fn turn_with_retry_recovers_from_transient_failures() {
        let p = FlakyProvider { calls: AtomicUsize::new(0), fail_times: 2, err: "API error (503): down".into() };
        let r = turn_streaming_with_retry(&p, &empty_turn(), "", Duration::ZERO, &|| None, &mut |_| {}).await.unwrap();
        assert_eq!(r.text, "ok");
        assert_eq!(p.calls.load(Ordering::SeqCst), 3, "two transient failures then success");
    }

    #[tokio::test]
    async fn turn_with_retry_fails_fast_on_permanent_error() {
        let p = FlakyProvider { calls: AtomicUsize::new(0), fail_times: 9, err: "API error (401): bad key".into() };
        let err = turn_streaming_with_retry(&p, &empty_turn(), "", Duration::ZERO, &|| None, &mut |_| {}).await.unwrap_err();
        assert!(err.contains("401"));
        assert_eq!(p.calls.load(Ordering::SeqCst), 1, "permanent error is not retried");
    }

    #[tokio::test]
    async fn turn_with_retry_gives_up_after_max_transient() {
        let p = FlakyProvider { calls: AtomicUsize::new(0), fail_times: 99, err: "Request failed: timed out".into() };
        let err = turn_streaming_with_retry(&p, &empty_turn(), "", Duration::ZERO, &|| None, &mut |_| {}).await.unwrap_err();
        assert!(err.contains("timed out"));
        // 1 initial attempt + MAX_TURN_RETRIES retries.
        assert_eq!(p.calls.load(Ordering::SeqCst), MAX_TURN_RETRIES + 1);
    }
}
